"use strict";
eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   FOUNDATIONS_MISSIONS: () => (/* binding */ FOUNDATIONS_MISSIONS)\n/* harmony export */ });\n// WORLD: FOUNDATIONS — 40 missions, numbers 201-240\n// 5 paths: Sound (201-208), Rhythm (209-216), Melody (217-224), Harmony (225-232), Tech (233-240)\nconst soundPath = [\n    {\n        slug: \"what-is-sound\",\n        world: \"foundations\",\n        number: 1,\n        title: \"What Is Sound?\",\n        tagline: \"Invisible waves that shake your ears.\",\n        xp: 40,\n        badge: {\n            slug: \"first-wave\",\n            name: \"First Wave\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Sound is mechanical energy — vibrations travelling through air as pressure waves. When something moves back and forth rapidly, it pushes air molecules into alternating zones of high and low pressure that radiate outward.\"\n            },\n            {\n                kind: \"para\",\n                text: \"Those pressure waves reach your eardrum, causing it to vibrate at the same rate. Your inner ear converts those vibrations into electrical signals your brain interprets as sound. Every kick drum, synth, and vocal is ultimately just air moving in a specific pattern.\"\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"Sound needs a medium to travel. In a vacuum there is no air, so no sound — hence the famous movie lie.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Frequency — how fast the wave vibrates (determines pitch)\",\n                    \"Amplitude — how strong the wave is (determines loudness)\",\n                    \"Timbre — the wave complexity (determines tone colour)\",\n                    \"Phase — where in its cycle the wave is at a given moment\"\n                ]\n            }\n        ],\n        sim: {\n            type: \"ear-training\"\n        },\n        quiz: [\n            {\n                q: \"Sound travels as\",\n                options: [\n                    \"Light beams\",\n                    \"Pressure waves through a medium\",\n                    \"Electrical signals\",\n                    \"Magnetic fields\"\n                ],\n                answer: 1,\n                explain: \"Sound is mechanical pressure waves — alternating compressions and rarefactions travelling through air or another medium.\",\n                hint: \"Think of ripples spreading out from a stone dropped in water.\"\n            },\n            {\n                q: \"What determines the pitch of a sound?\",\n                options: [\n                    \"Its amplitude\",\n                    \"Its frequency\",\n                    \"Its phase\",\n                    \"Its timbre\"\n                ],\n                answer: 1,\n                explain: \"Frequency (measured in Hz) is how many wave cycles occur per second. Higher frequency = higher pitch.\",\n                hint: \"A bird tweets fast; a bass drum hits slow. Which has higher frequency?\"\n            },\n            {\n                q: \"Sound cannot travel through\",\n                options: [\n                    \"Water\",\n                    \"Steel\",\n                    \"A vacuum\",\n                    \"Wood\"\n                ],\n                answer: 2,\n                explain: \"Sound needs a medium to propagate. In a vacuum there are no molecules to push, so no sound can travel.\",\n                hint: \"Space films always get this wrong.\"\n            },\n            {\n                q: \"The loudness of a sound is determined by its\",\n                options: [\n                    \"Frequency\",\n                    \"Timbre\",\n                    \"Amplitude\",\n                    \"Phase\"\n                ],\n                answer: 2,\n                explain: \"Amplitude is the height of the sound wave — bigger amplitude means more energy and louder volume.\",\n                hint: \"A bigger wave packs more punch.\"\n            }\n        ]\n    },\n    {\n        slug: \"frequency-pitch\",\n        world: \"foundations\",\n        number: 2,\n        title: \"Frequency & Pitch\",\n        tagline: \"Why a bass note is low and a flute is high.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Frequency is the number of complete wave cycles per second, measured in Hertz (Hz). Humans hear roughly 20 Hz to 20,000 Hz. Everything in music occupies a position in this spectrum.\"\n            },\n            {\n                kind: \"para\",\n                text: \"Pitch is your subjective perception of frequency. A4 is internationally defined as 440 Hz. Double the frequency and you go up one octave. Halve it and you go down an octave.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Sub-bass: 20-60 Hz — felt more than heard (kick body, bass rumble)\",\n                    \"Bass: 60-250 Hz — warmth, weight, fundamental of bass instruments\",\n                    \"Midrange: 250 Hz-4 kHz — most instruments and vocals live here\",\n                    \"High-mid: 4-8 kHz — presence, attack, consonants in speech\",\n                    \"Air: 8-20 kHz — sparkle, shimmer, breath\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Most production decisions happen between 80 Hz and 12 kHz. The extreme lows and highs still matter for feel and shimmer.\"\n            }\n        ],\n        sim: {\n            type: \"ear-training\"\n        },\n        quiz: [\n            {\n                q: \"What unit measures frequency?\",\n                options: [\n                    \"Decibels (dB)\",\n                    \"Hertz (Hz)\",\n                    \"Milliseconds (ms)\",\n                    \"Cents\"\n                ],\n                answer: 1,\n                explain: \"Hz (Hertz) = cycles per second. 440 Hz = 440 complete wave cycles every second.\",\n                hint: \"Named after physicist Heinrich Hertz.\"\n            },\n            {\n                q: \"If you double the frequency of a note, you go up\",\n                options: [\n                    \"A fifth\",\n                    \"An octave\",\n                    \"A semitone\",\n                    \"A major third\"\n                ],\n                answer: 1,\n                explain: \"Doubling frequency = one octave up. A4 = 440 Hz, A5 = 880 Hz. This is the fundamental law of pitch relationships.\",\n                hint: \"440 to 880. Same note, different register.\"\n            },\n            {\n                q: \"Approximately what frequency range can humans hear?\",\n                options: [\n                    \"2-2000 Hz\",\n                    \"20-20000 Hz\",\n                    \"200-20000 Hz\",\n                    \"20-200 Hz\"\n                ],\n                answer: 1,\n                explain: \"The healthy human hearing range is roughly 20 Hz (very low bass) to 20,000 Hz (high treble). This range narrows with age.\",\n                hint: \"The number is repeated: 20 to 20,000.\"\n            },\n            {\n                q: \"Where do most vocals and instruments sit in the frequency spectrum?\",\n                options: [\n                    \"Sub-bass (20-60 Hz)\",\n                    \"Midrange (250 Hz-4 kHz)\",\n                    \"Air (8-20 kHz)\",\n                    \"Infrasound (below 20 Hz)\"\n                ],\n                answer: 1,\n                explain: \"The midrange contains most energy from vocals, guitars, pianos, synths — which is why it is the most competitive range to EQ.\",\n                hint: \"The middle of the spectrum contains the middle of most music.\"\n            }\n        ]\n    },\n    {\n        slug: \"amplitude-volume\",\n        world: \"foundations\",\n        number: 3,\n        title: \"Amplitude & Volume\",\n        tagline: \"How we measure and control loudness.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Amplitude is the physical height of a sound wave — the measure of its pressure variation. We measure it in decibels (dB), a logarithmic scale that matches how our ears perceive loudness.\"\n            },\n            {\n                kind: \"para\",\n                text: \"The decibel scale is logarithmic because our ears are. A sound that is physically twice as powerful sounds only slightly louder — roughly 3 dB more. For a sound to seem twice as loud to a human listener, you need about 10 dB more power.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"0 dB SPL — threshold of human hearing\",\n                    \"30 dB — quiet bedroom at night\",\n                    \"60 dB — normal conversation\",\n                    \"85 dB — prolonged exposure causes hearing damage\",\n                    \"110 dB — live rock concert (front row)\",\n                    \"130 dB — threshold of pain\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"warn\",\n                text: \"In DAWs, 0 dBFS (Full Scale) is the maximum digital level. Going above it causes clipping — harsh digital distortion. Unlike acoustic levels, never exceed 0 dBFS.\"\n            }\n        ],\n        sim: {\n            type: \"knob-trainer\"\n        },\n        quiz: [\n            {\n                q: \"Decibels (dB) use a __ scale because our ears work that way.\",\n                options: [\n                    \"Linear\",\n                    \"Logarithmic\",\n                    \"Exponential\",\n                    \"Quadratic\"\n                ],\n                answer: 1,\n                explain: \"Our ears compress the enormous range of sounds we can hear into a manageable perception. Each 10 dB increase sounds roughly twice as loud despite being 10x more power.\",\n                hint: \"Doubling physical power only adds 3 dB, not 2x.\"\n            },\n            {\n                q: \"In a DAW, what happens if you exceed 0 dBFS?\",\n                options: [\n                    \"The track gets louder\",\n                    \"Digital clipping — harsh distortion\",\n                    \"The volume wraps around\",\n                    \"Nothing — it auto-limits\"\n                ],\n                answer: 1,\n                explain: \"0 dBFS is the absolute ceiling of digital audio. Exceeding it causes clipping where the waveform is literally cut off at the maximum value, creating harsh distortion.\",\n                hint: \"It is a hard ceiling. You cannot go higher — it clips.\"\n            },\n            {\n                q: \"What is dynamic range?\",\n                options: [\n                    \"The EQ curve of a sound\",\n                    \"The difference between loudest and softest levels in audio\",\n                    \"The frequency response of a speaker\",\n                    \"The stereo width of a mix\"\n                ],\n                answer: 1,\n                explain: \"Dynamic range = the spread between quietest and loudest. A large dynamic range feels expressive and live. Over-compression squashes dynamic range.\",\n                hint: \"Range = distance between two extremes. Loud and soft.\"\n            },\n            {\n                q: \"How many dB more does a sound need to seem twice as loud to humans?\",\n                options: [\n                    \"2 dB\",\n                    \"3 dB\",\n                    \"6 dB\",\n                    \"10 dB\"\n                ],\n                answer: 3,\n                explain: \"About 10 dB more power is needed for a sound to seem twice as loud — because of our logarithmic hearing.\",\n                hint: \"It is more than you would expect — our ears are very efficient compressors.\"\n            }\n        ]\n    },\n    {\n        slug: \"timbre-tone\",\n        world: \"foundations\",\n        number: 4,\n        title: \"Timbre & Tone Colour\",\n        tagline: \"Why a piano and guitar sound different on the same note.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Timbre is the tonal quality that makes a piano sound different from a guitar even when they play the same note at the same volume. It is determined by the sound's overtone structure — the combination of the fundamental frequency plus all its harmonics.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Bright: strong high-frequency harmonics (cymbal, harpsichord, distorted guitar)\",\n                    \"Warm: emphasised low-mids, rolled-off highs (acoustic bass, cello, Rhodes)\",\n                    \"Harsh: excessive upper-midrange harmonics (over-driven amp)\",\n                    \"Airy: prominent high-frequency content (flute, hi-hats, breathy vocals)\",\n                    \"Hollow: scooped midrange (flute, whistling)\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"In synthesis, you control timbre by choosing a waveform and then filtering it. In mixing, EQ adjusts timbre by boosting or cutting frequency regions.\"\n            }\n        ],\n        sim: {\n            type: \"ear-training\"\n        },\n        quiz: [\n            {\n                q: \"Timbre is best described as\",\n                options: [\n                    \"How loud a sound is\",\n                    \"How fast it vibrates\",\n                    \"The tonal quality or colour of a sound\",\n                    \"The spatial position of a sound\"\n                ],\n                answer: 2,\n                explain: \"Timbre is what makes sounds different from each other even when pitch and loudness are the same. It is determined by the overtone structure.\",\n                hint: \"Same note, different instrument — what is different?\"\n            },\n            {\n                q: \"What determines a sound's timbre?\",\n                options: [\n                    \"Its fundamental frequency only\",\n                    \"Its amplitude only\",\n                    \"The mix of its fundamental and overtones\",\n                    \"Its attack time only\"\n                ],\n                answer: 2,\n                explain: \"Timbre comes from the specific combination of the fundamental frequency plus all its overtones, each at different relative amplitudes.\",\n                hint: \"A guitar string vibrates at many frequencies simultaneously.\"\n            },\n            {\n                q: \"Which waveform is the purest — containing only a fundamental, no overtones?\",\n                options: [\n                    \"Square wave\",\n                    \"Sawtooth wave\",\n                    \"Triangle wave\",\n                    \"Sine wave\"\n                ],\n                answer: 3,\n                explain: \"A sine wave is a pure single frequency with no harmonics — the simplest possible waveform. All other waveforms contain multiple harmonics.\",\n                hint: \"The simplest mathematical wave.\"\n            },\n            {\n                q: \"In mixing, which tool primarily adjusts timbre?\",\n                options: [\n                    \"Compressor\",\n                    \"Reverb\",\n                    \"EQ\",\n                    \"Limiter\"\n                ],\n                answer: 2,\n                explain: \"An EQ (equaliser) boosts or cuts specific frequency ranges, directly changing the balance of harmonics and thus the perceived timbre of a sound.\",\n                hint: \"It adjusts the frequency balance — the mix of harmonics.\"\n            }\n        ]\n    },\n    {\n        slug: \"waveforms\",\n        world: \"foundations\",\n        number: 5,\n        title: \"Waveforms\",\n        tagline: \"The four fundamental shapes of sound.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A waveform is a graph of a sound's pressure variation over time. The four fundamental synthesiser waveforms — sine, square, sawtooth, and triangle — each have distinct harmonic content and character.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Sine wave — pure fundamental only. Clean, smooth. Sub bass, simple tones.\",\n                    \"Square wave — fundamental + odd harmonics. Hollow, woody, retro. Organs, clarinets.\",\n                    \"Sawtooth wave — fundamental + ALL harmonics. Bright, buzzy, rich. Strings, brass, bass.\",\n                    \"Triangle wave — fundamental + odd harmonics (weaker). Softer than square. Flutes, muted leads.\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"In synthesis, you start with one of these basic waveforms and then shape it — filtering removes harmonics, distortion adds them.\"\n            }\n        ],\n        sim: {\n            type: \"synth-playground\"\n        },\n        quiz: [\n            {\n                q: \"Which waveform contains ONLY a fundamental frequency?\",\n                options: [\n                    \"Square\",\n                    \"Sawtooth\",\n                    \"Sine\",\n                    \"Triangle\"\n                ],\n                answer: 2,\n                explain: \"The sine wave is the purest possible waveform — a single frequency with no harmonics.\",\n                hint: \"The simplest, smoothest wave.\"\n            },\n            {\n                q: \"A sawtooth wave contains\",\n                options: [\n                    \"Only odd harmonics\",\n                    \"Only even harmonics\",\n                    \"All harmonics (odd and even)\",\n                    \"No harmonics\"\n                ],\n                answer: 2,\n                explain: \"The sawtooth wave contains the fundamental plus ALL harmonics — both odd and even-numbered. This makes it bright and great for synthesis.\",\n                hint: \"The all-harmonics wave — brightest and richest.\"\n            },\n            {\n                q: \"What does audio clipping do to a waveform?\",\n                options: [\n                    \"Makes it louder without distortion\",\n                    \"Cuts off the peaks, flattening the tops\",\n                    \"Adds reverb\",\n                    \"Increases the frequency\"\n                ],\n                answer: 1,\n                explain: \"Clipping occurs when a waveform exceeds the maximum digital level. The peaks are literally cut flat, adding harsh high-frequency harmonics — digital distortion.\",\n                hint: \"The wave is clipped — its top cut off like a pruned hedge.\"\n            },\n            {\n                q: \"A square wave sounds hollow because it contains\",\n                options: [\n                    \"All harmonics\",\n                    \"No harmonics\",\n                    \"Only odd harmonics\",\n                    \"Only even harmonics\"\n                ],\n                answer: 2,\n                explain: \"Square waves contain the fundamental plus only odd-numbered harmonics. The missing even harmonics give them their characteristic hollow, woody sound.\",\n                hint: \"Missing the even numbers — hollow in the middle.\"\n            }\n        ]\n    },\n    {\n        slug: \"sound-in-space\",\n        world: \"foundations\",\n        number: 6,\n        title: \"Sound in Space\",\n        tagline: \"Reverb, reflection, and why rooms have character.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Sound bounces off walls, floors, ceilings and objects, reaching you from multiple directions and at different times. This combination of direct sound and reflections is what we call reverb, and it is why every space sounds different.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Direct sound — travels straight from source to ear\",\n                    \"Early reflections — first bounces off nearby surfaces (arrive within 50ms)\",\n                    \"Late reverb — dense, diffuse tail of countless reflections blending together\",\n                    \"RT60 — time for reverb to decay by 60 dB (standard room measurement)\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"In production, reverb is both a problem (in recording) and a tool (in mixing). We record in dry rooms, then add artificial reverb to place sounds in imagined spaces.\"\n            }\n        ],\n        sim: {\n            type: \"none\"\n        },\n        quiz: [\n            {\n                q: \"Reverb is caused by\",\n                options: [\n                    \"Sound waves speeding up\",\n                    \"Sound reflections off surfaces arriving at different times\",\n                    \"Changes in frequency over time\",\n                    \"Harmonic distortion\"\n                ],\n                answer: 1,\n                explain: \"Reverb is the accumulation of countless reflections from surfaces, each arriving at slightly different times.\",\n                hint: \"Clap in a cathedral — the sound bounces everywhere.\"\n            },\n            {\n                q: \"Hard surfaces (glass, concrete) mostly __ sound.\",\n                options: [\n                    \"Absorb\",\n                    \"Reflect\",\n                    \"Eliminate\",\n                    \"Generate\"\n                ],\n                answer: 1,\n                explain: \"Hard surfaces reflect sound energy. Soft surfaces (carpet, foam) absorb it. Recording studios use soft, irregular materials to deaden reflections.\",\n                hint: \"Hard = bouncy. Soft = absorby.\"\n            },\n            {\n                q: \"What is pre-delay in reverb?\",\n                options: [\n                    \"The loudness of the reverb\",\n                    \"The gap between the dry sound and the start of reverb\",\n                    \"The frequency of the reverb\",\n                    \"The stereo width of the reverb\"\n                ],\n                answer: 1,\n                explain: \"Pre-delay is the time between the original dry sound and when the reverb begins. It helps the dry signal arrive before the reverb cloud, keeping things clear.\",\n                hint: \"A small gap before the echo starts — letting the direct sound land first.\"\n            },\n            {\n                q: \"RT60 is a measurement of\",\n                options: [\n                    \"The highest frequency in a room\",\n                    \"How long it takes reverb to decay by 60 dB\",\n                    \"The recording level in dB\",\n                    \"The tempo of a track\"\n                ],\n                answer: 1,\n                explain: \"RT60 measures how long it takes for a sound to decay by 60 decibels in a room — the standard metric for how live or dead a room is.\",\n                hint: \"RT = Reverberation Time. 60 = 60 dB of decay.\"\n            }\n        ]\n    },\n    {\n        slug: \"overtones-harmonics\",\n        world: \"foundations\",\n        number: 7,\n        title: \"Overtones & Harmonics\",\n        tagline: \"The hidden notes inside every note.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"When you play a single note on any real instrument, you are actually hearing dozens of frequencies at once. The lowest is the fundamental. Above it are harmonics at integer multiples of the fundamental that give each instrument its tonal character.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"1st harmonic (fundamental) — the named pitch, strongest component\",\n                    \"2nd harmonic — one octave up from fundamental\",\n                    \"3rd harmonic — one octave + a fifth up\",\n                    \"4th harmonic — two octaves up\",\n                    \"Inharmonics — frequencies that are not integer multiples (bells, cymbals, drums)\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"The harmonic series is why certain intervals (octave, fifth, fourth) sound consonant — they share harmonics. Dissonant intervals share fewer harmonics, creating beating and tension.\"\n            }\n        ],\n        sim: {\n            type: \"ear-training\"\n        },\n        quiz: [\n            {\n                q: \"If a sound fundamental is 200 Hz, its 3rd harmonic is at\",\n                options: [\n                    \"300 Hz\",\n                    \"400 Hz\",\n                    \"600 Hz\",\n                    \"100 Hz\"\n                ],\n                answer: 2,\n                explain: \"Harmonics are at integer multiples: 3rd = 3 x 200 Hz = 600 Hz.\",\n                hint: \"3rd harmonic = 3 times the fundamental.\"\n            },\n            {\n                q: \"Why do octave intervals sound pure and stable?\",\n                options: [\n                    \"They have the same amplitude\",\n                    \"Their frequencies share many common harmonics\",\n                    \"They are exactly 100 Hz apart\",\n                    \"They are both in the bass range\"\n                ],\n                answer: 1,\n                explain: \"An octave (2:1 ratio) means every harmonic of the higher note coincides with an even harmonic of the lower note — maximum harmonic overlap, maximum consonance.\",\n                hint: \"Consonance = shared harmonics. Octave = maximum sharing.\"\n            },\n            {\n                q: \"Which type of sound has overtones that do NOT follow the harmonic series?\",\n                options: [\n                    \"Violin string\",\n                    \"Brass instrument\",\n                    \"Bell or cymbal\",\n                    \"Flute\"\n                ],\n                answer: 2,\n                explain: \"Bells, cymbals and drums produce inharmonic overtones — their vibration modes do not follow integer multiples of the fundamental, making pitch harder to perceive.\",\n                hint: \"Bells sound clangy — hard to sing along to a specific pitch.\"\n            },\n            {\n                q: \"Adding more high-frequency harmonics to a sound makes it\",\n                options: [\n                    \"Warmer and rounder\",\n                    \"Brighter with more presence\",\n                    \"Quieter\",\n                    \"Lower in pitch\"\n                ],\n                answer: 1,\n                explain: \"High-frequency harmonics add brightness, presence, and edge to a sound. This is what EQ high-shelf boosts and saturation effects do.\",\n                hint: \"High harmonics = high frequency energy = brightness.\"\n            }\n        ]\n    },\n    {\n        slug: \"how-we-hear\",\n        world: \"foundations\",\n        number: 8,\n        title: \"How We Hear\",\n        tagline: \"Ears, brains, and why context changes everything.\",\n        xp: 40,\n        badge: {\n            slug: \"sound-scientist\",\n            name: \"Sound Scientist\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Hearing is not passive reception — it is active interpretation. Your ears capture sound waves; your brain reconstructs a rich sonic world from that data, filling in gaps and making constant perceptual decisions.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Frequency masking — a loud sound makes nearby quieter frequencies inaudible\",\n                    \"Temporal masking — a loud sound can mask quieter sounds shortly before or after it\",\n                    \"Equal loudness contours — our ears are more sensitive to midrange than bass or treble at low volumes\",\n                    \"Binaural hearing — tiny time and level differences between our two ears let us locate sound in space\",\n                    \"Auditory fatigue — prolonged loud exposure temporarily reduces sensitivity\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Mix at moderate volumes (around 75-80 dB SPL). Loud mixing causes ear fatigue and the Fletcher-Munson effect — you over-compensate bass and treble because they feel weaker at high volume.\"\n            }\n        ],\n        sim: {\n            type: \"ear-training\"\n        },\n        quiz: [\n            {\n                q: \"What structure in the ear separates frequencies along its length?\",\n                options: [\n                    \"The eardrum\",\n                    \"The ossicles\",\n                    \"The cochlea\",\n                    \"The auditory nerve\"\n                ],\n                answer: 2,\n                explain: \"The cochlea is a fluid-filled spiral tuned along its length — high frequencies activate hair cells near the entrance, low frequencies activate cells near the apex.\",\n                hint: \"It is spiral-shaped — like a snail shell.\"\n            },\n            {\n                q: \"Frequency masking means\",\n                options: [\n                    \"A filter that removes a frequency\",\n                    \"A loud sound makes nearby quieter sounds inaudible\",\n                    \"Reversing the phase of a frequency\",\n                    \"Adding harmonics to a frequency\"\n                ],\n                answer: 1,\n                explain: \"When a loud sound is present, it masks nearby quieter sounds — making them harder or impossible to hear.\",\n                hint: \"The loud drowns out the quiet — at similar frequencies.\"\n            },\n            {\n                q: \"Why should you mix at moderate volume levels?\",\n                options: [\n                    \"To save electricity\",\n                    \"To avoid auditory fatigue and equal-loudness curve effects\",\n                    \"To make mixes sound better on phones\",\n                    \"Loud mixes clip automatically\"\n                ],\n                answer: 1,\n                explain: \"At high volumes all frequencies seem equally loud. At moderate volumes the ear's natural frequency response reveals real balance issues. Also ear fatigue from loud monitoring leads to poor decisions.\",\n                hint: \"Loud = tired ears + skewed frequency perception.\"\n            },\n            {\n                q: \"Which physical cause leads to permanent hearing damage?\",\n                options: [\n                    \"Listening to music at any volume\",\n                    \"Prolonged exposure to sounds above 85 dB\",\n                    \"Using headphones vs speakers\",\n                    \"Listening to bass-heavy music\"\n                ],\n                answer: 1,\n                explain: \"Sound above 85 dB SPL over extended periods destroys cochlear hair cells irreversibly. There are no hair cell stem cells in adult humans — once damaged, gone forever.\",\n                hint: \"85 dB is the threshold. Time + level = damage.\"\n            }\n        ]\n    }\n];\nconst rhythmPath = [\n    {\n        slug: \"what-is-rhythm\",\n        world: \"foundations\",\n        number: 9,\n        title: \"What Is Rhythm?\",\n        tagline: \"Pattern, pulse and the feel of time.\",\n        xp: 40,\n        badge: {\n            slug: \"time-keeper\",\n            name: \"Time Keeper\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Rhythm is the organisation of sounds in time — when notes happen and when they do not. The fundamental element is the pulse: a steady regular beat underlying most music. Source: learningmusic.ableton.com/make-beats\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Pulse — the steady underlying beat (like a heartbeat or clock)\",\n                    \"Tempo — how fast the pulse is (measured in BPM)\",\n                    \"Metre — how pulses group into recurring patterns (4/4, 3/4, etc.)\",\n                    \"Accent — emphasis on certain beats that creates the feel\",\n                    \"Groove — the human feel around the rhythm\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"Rhythm exists in relationships between sounds. A single note has no rhythm. Two notes at different times start to establish one. The pattern of when things happen is everything.\"\n            }\n        ],\n        sim: {\n            type: \"drum-pad\"\n        },\n        quiz: [\n            {\n                q: \"The pulse in music is\",\n                options: [\n                    \"The melody of a song\",\n                    \"A steady regular underlying beat\",\n                    \"The loudest sound in a mix\",\n                    \"The tempo in BPM\"\n                ],\n                answer: 1,\n                explain: \"The pulse is the steady heartbeat underlying music — the beat you tap your foot to even if it is not explicitly played. Source: learningmusic.ableton.com/make-beats\",\n                hint: \"Think: metronome click. Steady, regular, constant.\"\n            },\n            {\n                q: \"Rhythm is primarily about\",\n                options: [\n                    \"Which notes are played\",\n                    \"When sounds happen in time\",\n                    \"How loud sounds are\",\n                    \"Which key a song is in\"\n                ],\n                answer: 1,\n                explain: \"Rhythm is the organisation of sound in time — the pattern of when events occur and do not occur.\",\n                hint: \"Replace all notes with the same click — what is left? That is rhythm.\"\n            },\n            {\n                q: \"What is groove in rhythm?\",\n                options: [\n                    \"Playing exactly on the grid\",\n                    \"The human feel around the beat — timing variations that create motion\",\n                    \"The BPM of a track\",\n                    \"A type of software\"\n                ],\n                answer: 1,\n                explain: \"Groove is the subtle timing variations around the beat grid that make rhythm feel human and alive.\",\n                hint: \"A drum machine plays exactly on grid. A human drummer has groove.\"\n            },\n            {\n                q: \"What is metre in music?\",\n                options: [\n                    \"The speed of a track\",\n                    \"How pulses group into recurring patterns\",\n                    \"The pitch of the bass note\",\n                    \"The length of a song\"\n                ],\n                answer: 1,\n                explain: \"Metre describes how beats group together in recurring patterns. 4/4 = four beats per bar. 3/4 = three per bar.\",\n                hint: \"How many counts before the pattern repeats?\"\n            }\n        ]\n    },\n    {\n        slug: \"tempo-bpm\",\n        world: \"foundations\",\n        number: 10,\n        title: \"Tempo and BPM\",\n        tagline: \"Measuring the speed of music.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Tempo is the speed of music measured in BPM (Beats Per Minute). 60 BPM = one beat per second. 120 BPM = two beats per second. Source: learningmusic.ableton.com/make-beats\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"50-70 BPM — very slow, ballads, ambient\",\n                    \"70-95 BPM — slow groove, blues, R&B, hip-hop\",\n                    \"95-115 BPM — mid-tempo, pop, lo-fi\",\n                    \"115-130 BPM — dance, house, 4x4 club music\",\n                    \"130-145 BPM — techno, hard house, trance\",\n                    \"160-180 BPM — drum and bass, jungle\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Trap and drill use 130-150 BPM but with a half-time feel — the kick and snare pattern makes it feel like 65-75 BPM. Sub-genres often play with perceived tempo vs actual tempo.\"\n            }\n        ],\n        sim: {\n            type: \"bpm-tap\"\n        },\n        quiz: [\n            {\n                q: \"What does BPM stand for?\",\n                options: [\n                    \"Bass Per Measure\",\n                    \"Beats Per Minute\",\n                    \"Bar Phase Marker\",\n                    \"Beat Pulse Modulator\"\n                ],\n                answer: 1,\n                explain: \"BPM = Beats Per Minute. The universal speed measurement in music production and DJing.\",\n                hint: \"Think: a stopwatch and a metronome.\"\n            },\n            {\n                q: \"House music typically runs at\",\n                options: [\n                    \"70-90 BPM\",\n                    \"120-130 BPM\",\n                    \"150-165 BPM\",\n                    \"180-200 BPM\"\n                ],\n                answer: 1,\n                explain: \"House music runs 120-130 BPM, built around a four-on-the-floor kick drum. Source: learningmusic.ableton.com\",\n                hint: \"Fast enough to dance to, grounded enough to breathe.\"\n            },\n            {\n                q: \"At 120 BPM there are __ beats per second.\",\n                options: [\n                    \"1\",\n                    \"2\",\n                    \"4\",\n                    \"0.5\"\n                ],\n                answer: 1,\n                explain: \"120 BPM divided by 60 seconds = 2 beats per second.\",\n                hint: \"120 BPM divided by 60 seconds per minute.\"\n            },\n            {\n                q: \"Drum and bass typically runs at\",\n                options: [\n                    \"120-130 BPM\",\n                    \"140-150 BPM\",\n                    \"160-180 BPM\",\n                    \"200+ BPM\"\n                ],\n                answer: 2,\n                explain: \"Drum and bass (DnB) typically runs at 160-180 BPM — the fastest mainstream dance genre.\",\n                hint: \"The fastest mainstream dance genre.\"\n            }\n        ]\n    },\n    {\n        slug: \"bars-time-signatures\",\n        world: \"foundations\",\n        number: 11,\n        title: \"Bars and Time Signatures\",\n        tagline: \"How music is divided into repeating groups.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A bar contains a set number of beats. The time signature tells you how many beats are in each bar and what note value counts as one beat. Source: learningmusic.ableton.com/make-beats\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"4/4 — four quarter-note beats per bar. Pop, rock, house, hip-hop, techno\",\n                    \"3/4 — three beats per bar. Waltz, some ballads\",\n                    \"6/8 — six eighth-note beats grouped in two threes. Gospel, blues\",\n                    \"5/4 — five beats (Dave Brubeck Take Five, prog rock)\",\n                    \"7/8 — seven beats, Balkan music, math rock\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"In a DAW, the session is organised into bars. Loops are usually 1, 2, 4, 8, or 16 bars. Knowing where bar 1 is matters in production and DJing. Source: Ableton Live manual.\"\n            }\n        ],\n        sim: {\n            type: \"drum-pad\"\n        },\n        quiz: [\n            {\n                q: \"In 4/4 time, how many beats are in each bar?\",\n                options: [\n                    \"2\",\n                    \"3\",\n                    \"4\",\n                    \"8\"\n                ],\n                answer: 2,\n                explain: \"The top number of the time signature tells you beats per bar. 4/4 = 4 beats per bar.\",\n                hint: \"The top number of the time signature = beats per bar.\"\n            },\n            {\n                q: \"What is the downbeat?\",\n                options: [\n                    \"Beat 2 of a bar\",\n                    \"The last beat of a bar\",\n                    \"Beat 1 — the strongest most grounded beat\",\n                    \"Any quiet beat\"\n                ],\n                answer: 2,\n                explain: \"The downbeat is beat 1 — the first and strongest beat of each bar. The home base where the bar restarts. DJs align transitions to the downbeat.\",\n                hint: \"Count: ONE two three four. The ONE is the downbeat.\"\n            },\n            {\n                q: \"A waltz uses which time signature?\",\n                options: [\n                    \"4/4\",\n                    \"3/4\",\n                    \"6/8\",\n                    \"5/4\"\n                ],\n                answer: 1,\n                explain: \"A waltz is in 3/4 — three beats per bar. ONE two three ONE two three.\",\n                hint: \"Waltz: one-two-three, one-two-three. How many in a group?\"\n            },\n            {\n                q: \"In a DAW, why do bars matter?\",\n                options: [\n                    \"They set the volume level\",\n                    \"They determine clip lengths, loop points and arrangement structure\",\n                    \"They control the pitch\",\n                    \"They define the stereo width\"\n                ],\n                answer: 1,\n                explain: \"Everything in a DAW is bar-based. Clip lengths are multiples of bars. Automation aligns to bars. Bars are the building blocks.\",\n                hint: \"The grid in your DAW? That is bars.\"\n            }\n        ]\n    },\n    {\n        slug: \"groove-feel\",\n        world: \"foundations\",\n        number: 12,\n        title: \"Groove and Feel\",\n        tagline: \"Why a drum machine does not always sound human.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Groove is the subtle timing variation around the beat grid that makes rhythm feel alive. When every note lands exactly on the mathematical grid, music can sound rigid and lifeless. Source: Ableton Live manual — Groove Pool.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Laid back — notes placed slightly after the beat. Relaxed, deep, hip-hop feel\",\n                    \"Pushing — notes placed slightly before the beat. Urgent, excited, forward motion\",\n                    \"Velocity variation — different hit strengths for natural dynamics\",\n                    \"Humanise — random small timing variations added to a rigid MIDI pattern\",\n                    \"Quantise — snapping notes to the grid (removes human variation)\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"In Ableton Live, the Groove Pool lets you extract the groove from any audio sample and apply it to MIDI. You can make programmed drums feel like a specific famous drum break. Source: Ableton Live manual — Groove Pool.\"\n            }\n        ],\n        sim: {\n            type: \"groove-extractor\"\n        },\n        quiz: [\n            {\n                q: \"What is swing in music production?\",\n                options: [\n                    \"Playing notes out of key\",\n                    \"Making off-beats slightly later to create a bouncy feel\",\n                    \"Playing faster than the tempo\",\n                    \"Adding reverb to drums\"\n                ],\n                answer: 1,\n                explain: \"Swing delays the off-beats slightly, giving rhythm a bouncy triplet-like feel. 50% = straight, 67% = full triplet shuffle. Source: Ableton Live manual.\",\n                hint: \"Jazz and hip-hop both use heavy swing. It makes things bounce.\"\n            },\n            {\n                q: \"Quantising a MIDI part means\",\n                options: [\n                    \"Adding swing to it\",\n                    \"Snapping all notes exactly to the grid\",\n                    \"Transposing it to a new key\",\n                    \"Adding velocity variation\"\n                ],\n                answer: 1,\n                explain: \"Quantise moves MIDI notes to the nearest grid position, making them rhythmically exact. Over-quantise and it sounds lifeless.\",\n                hint: \"Snap to grid — perfectly precise.\"\n            },\n            {\n                q: \"A laid back groove means notes are placed\",\n                options: [\n                    \"Exactly on the beat\",\n                    \"Slightly before the beat\",\n                    \"Slightly after the beat\",\n                    \"Randomly throughout the bar\"\n                ],\n                answer: 2,\n                explain: \"Laid back = notes land slightly after the mathematical beat. Creates a relaxed deep feel — classic in hip-hop, soul, blues.\",\n                hint: \"Laid back = relaxed. Late to the party.\"\n            },\n            {\n                q: \"The Groove Pool in Ableton\",\n                options: [\n                    \"Generates random beats\",\n                    \"Extracts groove timing from audio and applies it to MIDI\",\n                    \"Sets the master BPM\",\n                    \"Records audio loops\"\n                ],\n                answer: 1,\n                explain: \"The Groove Pool lets you drag any audio clip in, extract its rhythmic feel, and apply that groove to any MIDI clip. Source: Ableton Live manual.\",\n                hint: \"Steal the feel from a real drum break.\"\n            }\n        ]\n    },\n    {\n        slug: \"syncopation\",\n        world: \"foundations\",\n        number: 13,\n        title: \"Syncopation\",\n        tagline: \"Hitting the off-beat — where energy hides.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Syncopation is placing accents on beats or subdivisions that are typically unaccented — the off-beats between the main pulse. It creates rhythmic surprise, forward motion and tension. Most popular music is built on syncopation. Source: learningmusic.ableton.com\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Backbeat — emphasis on beats 2 and 4 (pop/rock snare, handclap)\",\n                    \"Off-beat eighth notes — accenting the and between beats\",\n                    \"Anticipated beat — hitting just before the bar line (common in funk bass)\",\n                    \"Tied syncopation — a note starts on an off-beat and holds through the strong beat\",\n                    \"Clave — the foundational syncopated pattern of Afro-Cuban music\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"Syncopation is fundamentally African in origin. West African rhythmic systems form the foundation of virtually all popular music: blues, jazz, R&B, rock, funk, hip-hop, house, techno.\"\n            }\n        ],\n        sim: {\n            type: \"drum-pad\"\n        },\n        quiz: [\n            {\n                q: \"Syncopation means\",\n                options: [\n                    \"Playing only on the main beats\",\n                    \"Accenting off-beats or weak beats unexpectedly\",\n                    \"Playing in a different time signature\",\n                    \"Slowing down the tempo\"\n                ],\n                answer: 1,\n                explain: \"Syncopation shifts emphasis to the wrong beats — the off-beats, weak beats, spaces between the main pulse.\",\n                hint: \"Hitting where you are not supposed to hit.\"\n            },\n            {\n                q: \"In 4/4 time the backbeat is on\",\n                options: [\n                    \"Beats 1 and 3\",\n                    \"Beats 2 and 4\",\n                    \"All four beats\",\n                    \"The eighth-note off-beats\"\n                ],\n                answer: 1,\n                explain: \"The backbeat is beats 2 and 4 — where the snare or clap usually lands. The heartbeat of pop, rock, and most dance music.\",\n                hint: \"When do you clap along to a pop song? The 2 and 4.\"\n            },\n            {\n                q: \"Which tradition is the primary origin of syncopation in popular music?\",\n                options: [\n                    \"European classical music\",\n                    \"West African rhythmic traditions\",\n                    \"Indian classical music\",\n                    \"East Asian music\"\n                ],\n                answer: 1,\n                explain: \"West African musical traditions, carried through the transatlantic slave trade, gave popular music its syncopated rhythmic DNA.\",\n                hint: \"Afro-Cuban clave, blues, jazz — trace their rhythmic roots.\"\n            },\n            {\n                q: \"An anticipated beat hits\",\n                options: [\n                    \"Slightly late\",\n                    \"Just before the downbeat creating forward momentum\",\n                    \"Tied over a bar line\",\n                    \"Exactly on the beat\"\n                ],\n                answer: 1,\n                explain: \"An anticipated beat hits just before the bar line — arriving early to create a feeling of rushing forward into the next bar. Very common in funk bass.\",\n                hint: \"It anticipates what is coming — arrives early.\"\n            }\n        ]\n    },\n    {\n        slug: \"polyrhythm\",\n        world: \"foundations\",\n        number: 14,\n        title: \"Polyrhythm\",\n        tagline: \"Two rhythms at once — and why it hypnotises.\",\n        xp: 50,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Polyrhythm is the simultaneous use of two or more contrasting rhythms. The most common example is 3 against 2 — one voice plays three evenly-spaced notes while another plays two over the same duration.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"3:2 — three beats against two (the fundamental polyrhythm)\",\n                    \"4:3 — four against three\",\n                    \"Hemiola — alternating between groupings of 3 and 2 within 6/8\",\n                    \"African clave — a 3:2 syncopated pattern foundational to Cuban and jazz music\",\n                    \"Trap hi-hats — often places a 3-beat hi-hat pattern over a 4-beat kick grid\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Try programming an eighth-note hi-hat pattern in groups of three (every 3 sixteenths) over a straight four-on-the-floor kick. The resulting 3-against-4 creates hypnotic forward motion — used constantly in minimal techno and Afrobeats.\"\n            }\n        ],\n        sim: {\n            type: \"drum-pad\"\n        },\n        quiz: [\n            {\n                q: \"Polyrhythm means\",\n                options: [\n                    \"Playing one complex rhythm\",\n                    \"Using two or more contrasting rhythms simultaneously\",\n                    \"Changing time signature mid-song\",\n                    \"Playing faster than normal\"\n                ],\n                answer: 1,\n                explain: \"Polyrhythm = multiple different rhythmic patterns happening at the same time. The interlock between them creates complexity that none of the individual parts has alone.\",\n                hint: \"Poly = many. Multiple rhythms simultaneously.\"\n            },\n            {\n                q: \"In a 3:2 polyrhythm you hear\",\n                options: [\n                    \"Three beats per bar\",\n                    \"Three evenly-spaced notes against two evenly-spaced notes in the same time\",\n                    \"A time signature of 3/2\",\n                    \"Three loud beats and two quiet beats\"\n                ],\n                answer: 1,\n                explain: \"3:2 = three notes evenly distributed while two notes are evenly distributed in the same duration. They only align at the start and end of the cycle.\",\n                hint: \"Two players, same duration, different subdivisions — they pull against each other.\"\n            },\n            {\n                q: \"Polyrhythm originated primarily in\",\n                options: [\n                    \"European classical music\",\n                    \"Indian classical music\",\n                    \"West African drumming traditions\",\n                    \"Medieval church music\"\n                ],\n                answer: 2,\n                explain: \"West African drumming ensembles are built entirely on polyrhythm — multiple interlocking rhythmic patterns layered simultaneously.\",\n                hint: \"Djembe circles. Talking drums. Ewe, Yoruba, Akan drumming traditions.\"\n            },\n            {\n                q: \"How do some trap producers use polyrhythm?\",\n                options: [\n                    \"By using 7/8 time\",\n                    \"By placing a 3-beat hi-hat pattern over a 4-beat kick grid\",\n                    \"By removing all percussion\",\n                    \"By using multiple tempos\"\n                ],\n                answer: 1,\n                explain: \"A common trap technique is programming hi-hats in groups of three sixteenth notes over a standard 4/4 kick — creating a 3-against-4 polyrhythm.\",\n                hint: \"Count hi-hats: 1-2-3 1-2-3 over a 1-2-3-4 kick.\"\n            }\n        ]\n    },\n    {\n        slug: \"note-values\",\n        world: \"foundations\",\n        number: 15,\n        title: \"Note Values and Subdivision\",\n        tagline: \"Whole notes, halves, quarters, eighths — the maths of rhythm.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Note values describe how long a note is held relative to the bar. In 4/4 time, a whole note fills an entire bar (4 beats). A half note = 2 beats. A quarter note = 1 beat. An eighth note = half a beat. Source: learningmusic.ableton.com/make-beats\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Whole note (semibreve) — 4 beats in 4/4\",\n                    \"Half note (minim) — 2 beats\",\n                    \"Quarter note (crotchet) — 1 beat — the standard BPM pulse\",\n                    \"Eighth note (quaver) — 1/2 beat — 8 per bar in 4/4\",\n                    \"Sixteenth note (semiquaver) — 1/4 beat — 16 per bar in 4/4\",\n                    \"Triplets — three notes in the space of two (gives swing feel)\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"The piano roll in your DAW shows time on the horizontal axis. Set the grid to 1/16 and you see 16 positions per bar — each one a sixteenth note. Source: Ableton Live manual — MIDI notes and velocity.\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"How many eighth notes fit in one bar of 4/4?\",\n                options: [\n                    \"4\",\n                    \"6\",\n                    \"8\",\n                    \"16\"\n                ],\n                answer: 2,\n                explain: \"In 4/4 there are 4 beats. An eighth note = half a beat. 4 beats x 2 eighth notes per beat = 8 per bar.\",\n                hint: \"One beat = two eighth notes. Four beats = eight eighth notes.\"\n            },\n            {\n                q: \"A quarter note lasts\",\n                options: [\n                    \"A quarter of a beat\",\n                    \"One beat (in 4/4)\",\n                    \"Four beats\",\n                    \"Half a bar\"\n                ],\n                answer: 1,\n                explain: \"In 4/4 a quarter note lasts exactly one beat — the standard pulse unit that BPM is measured in.\",\n                hint: \"Quarter note = one quarter of a 4/4 bar = one beat.\"\n            },\n            {\n                q: \"Sixteenth notes are how many per bar in 4/4?\",\n                options: [\n                    \"8\",\n                    \"12\",\n                    \"16\",\n                    \"32\"\n                ],\n                answer: 2,\n                explain: \"Sixteenth note = 1/4 beat. 4 beats x 4 sixteenth notes per beat = 16 per bar.\",\n                hint: \"16 per bar — hence the name.\"\n            },\n            {\n                q: \"A dotted quarter note lasts\",\n                options: [\n                    \"1 beat\",\n                    \"1.5 beats\",\n                    \"2 beats\",\n                    \"0.75 beats\"\n                ],\n                answer: 1,\n                explain: \"A dot adds half the note value. Quarter note = 1 beat. Half of 1 beat = 0.5 beats. Dotted quarter = 1.5 beats.\",\n                hint: \"Dot = add half again. 1 + (1 divided by 2) = 1.5.\"\n            }\n        ]\n    },\n    {\n        slug: \"rhythm-in-production\",\n        world: \"foundations\",\n        number: 16,\n        title: \"Rhythm in Production\",\n        tagline: \"How rhythm works inside a DAW.\",\n        xp: 40,\n        badge: {\n            slug: \"rhythm-builder\",\n            name: \"Rhythm Builder\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"In a DAW, rhythm is managed through the piano roll (for MIDI), the drum rack (for individual drum hits), and the audio clip editor. Understanding note values and bar structure lets you work confidently in any of these. Source: Ableton Live manual.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Step sequencer — grid of boxes each representing a subdivision\",\n                    \"Piano roll — horizontal grid where you draw notes of any length at any position\",\n                    \"MIDI clip — stores note data that an instrument plays back at the project tempo\",\n                    \"Drum rack — maps individual drum sounds to MIDI notes, one pad = one sound\",\n                    \"Quantise — snap MIDI notes to the nearest grid division to tighten timing\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Record your rhythmic ideas at a slower tempo first. Speed the project up once the parts are recorded. Much easier to play accurately at 80 BPM then raise to 140 than to record at 140 from the start.\"\n            }\n        ],\n        sim: {\n            type: \"drum-pad\"\n        },\n        quiz: [\n            {\n                q: \"In a DAW drum rack each pad represents\",\n                options: [\n                    \"A bar of music\",\n                    \"A MIDI note mapped to a specific drum sound\",\n                    \"A tempo setting\",\n                    \"An audio track\"\n                ],\n                answer: 1,\n                explain: \"A drum rack maps individual drum sounds to specific MIDI notes. Triggering MIDI note C1 plays the kick, D1 the snare, etc. Source: Ableton Live manual — Drum Rack.\",\n                hint: \"Pad = MIDI note = drum sound. One-to-one mapping.\"\n            },\n            {\n                q: \"Warping audio in a DAW means\",\n                options: [\n                    \"Reversing the audio\",\n                    \"Stretching or compressing audio so its rhythm aligns with the project tempo without changing pitch\",\n                    \"Adding distortion\",\n                    \"Exporting the file\"\n                ],\n                answer: 1,\n                explain: \"Warping time-stretches audio so it plays at the project BPM without changing pitch. Source: Ableton Live manual — Warping.\",\n                hint: \"Time-stretch to fit the grid — tempo change without pitch change.\"\n            },\n            {\n                q: \"Why add drum pattern variations every 4 bars?\",\n                options: [\n                    \"To change the BPM\",\n                    \"To prevent monotony and signal structural transitions\",\n                    \"To add reverb\",\n                    \"To fix timing errors\"\n                ],\n                answer: 1,\n                explain: \"Using the same drum loop for an entire track becomes monotonous. Small variations create interest and signal section changes.\",\n                hint: \"Four bars and repeat gets boring. Mix it up.\"\n            },\n            {\n                q: \"Recording at a slower BPM first then speeding up is useful because\",\n                options: [\n                    \"It saves file space\",\n                    \"It is easier to play accurately at lower tempos and the grid scales up cleanly\",\n                    \"It changes the key of the recording\",\n                    \"It automatically adds swing\"\n                ],\n                answer: 1,\n                explain: \"Performing at lower BPM lets you play each note accurately. Once recorded, raise the project tempo and MIDI scales perfectly.\",\n                hint: \"Practice slow, perform fast. DAWs work the same way.\"\n            }\n        ]\n    }\n];\nconst melodyPath = [\n    {\n        slug: \"notes-and-octaves\",\n        world: \"foundations\",\n        number: 17,\n        title: \"Notes and Octaves\",\n        tagline: \"The 12 notes and why the pattern repeats.\",\n        xp: 40,\n        badge: {\n            slug: \"note-finder\",\n            name: \"Note Finder\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Western music uses 12 pitch classes arranged in a repeating cycle called the chromatic scale. Source: learningmusic.ableton.com/notes-and-scales\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Middle C is C4 — roughly the centre of a standard 88-key piano\",\n                    \"Sharps (#) raise a note by one semitone — C# is one above C\",\n                    \"Flats (b) lower a note by one semitone — Bb is one below B\",\n                    \"Enharmonic equivalents — same pitch, different name (C# = Db)\",\n                    \"Scientific pitch notation — C4, D4, E4 (number = octave number)\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"On a piano keyboard, white keys are the 7 natural notes. Black keys are the sharps/flats. The pattern of 2 black keys + gap + 3 black keys repeats every octave — use it to find any note.\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"How many semitones are in one octave?\",\n                options: [\n                    \"7\",\n                    \"8\",\n                    \"10\",\n                    \"12\"\n                ],\n                answer: 3,\n                explain: \"There are 12 semitones in one octave — all the half-step steps from C to the next C including sharps and flats.\",\n                hint: \"Count every key (white AND black) from C to the next C on a piano.\"\n            },\n            {\n                q: \"Middle C in scientific pitch notation is\",\n                options: [\n                    \"C3\",\n                    \"C4\",\n                    \"C5\",\n                    \"C6\"\n                ],\n                answer: 1,\n                explain: \"Middle C = C4. It sits in the middle of a standard 88-key piano keyboard. Source: learningmusic.ableton.com/notes-and-scales\",\n                hint: \"Middle C = C4. The 4 is the octave number.\"\n            },\n            {\n                q: \"C# and Db are\",\n                options: [\n                    \"Different pitches\",\n                    \"The same pitch — enharmonic equivalents\",\n                    \"An octave apart\",\n                    \"A perfect fifth apart\"\n                ],\n                answer: 1,\n                explain: \"C# (C sharp) and Db (D flat) are enharmonic equivalents — the same pitch on a keyboard, just named differently depending on context.\",\n                hint: \"Same black key, two names.\"\n            },\n            {\n                q: \"Going up one octave multiplies the frequency by\",\n                options: [\n                    \"10\",\n                    \"3\",\n                    \"2\",\n                    \"1.5\"\n                ],\n                answer: 2,\n                explain: \"One octave up = frequency x 2. A4 = 440 Hz, A5 = 880 Hz. Each octave doubles the frequency.\",\n                hint: \"Double the frequency = same note one octave higher.\"\n            }\n        ]\n    },\n    {\n        slug: \"major-scale\",\n        world: \"foundations\",\n        number: 18,\n        title: \"The Major Scale\",\n        tagline: \"Do Re Mi — the brightest most universal scale.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"The major scale is the most fundamental pitch collection in Western music. Seven notes in a specific pattern of whole steps (W) and half steps (H): W W H W W W H. Starting on C: C D E F G A B. Source: learningmusic.ableton.com/notes-and-scales\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"C major: C D E F G A B (all white keys)\",\n                    \"G major: G A B C D E F# (one sharp)\",\n                    \"F major: F G A Bb C D E (one flat)\",\n                    \"Pattern: W W H W W W H from any starting note\",\n                    \"Each note has a number (scale degree): 1 2 3 4 5 6 7\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Scale degrees matter more than note names. The 1 (tonic) is always home. The 5 (dominant) creates tension. The 7 (leading tone) wants to resolve up to 1. These relationships are the same regardless of key. Source: learningmusic.ableton.com\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"The major scale follows which step pattern?\",\n                options: [\n                    \"W H W W H W W\",\n                    \"W W H W W W H\",\n                    \"H W W H W W W\",\n                    \"All whole steps\"\n                ],\n                answer: 1,\n                explain: \"W W H W W W H — whole, whole, half, whole, whole, whole, half. Follow this pattern from any note to build a major scale.\",\n                hint: \"Two whole steps then a half — then three whole steps then a half.\"\n            },\n            {\n                q: \"C major uses\",\n                options: [\n                    \"All black keys\",\n                    \"All white keys\",\n                    \"Mixed black and white keys\",\n                    \"Only C E and G\"\n                ],\n                answer: 1,\n                explain: \"C major uses all seven white keys (C D E F G A B) with no sharps or flats.\",\n                hint: \"Play only the white keys from C to C. That is C major.\"\n            },\n            {\n                q: \"The major scale sounds happy or bright primarily because of its\",\n                options: [\n                    \"Minor third (3 semitones)\",\n                    \"Major third (4 semitones)\",\n                    \"Perfect fifth\",\n                    \"Minor seventh\"\n                ],\n                answer: 1,\n                explain: \"The major third (4 semitones from root to 3rd scale degree) gives major scales their bright quality. The minor scale lowers this by one semitone.\",\n                hint: \"The 3rd degree is the key difference between major and minor.\"\n            },\n            {\n                q: \"What is a scale degree?\",\n                options: [\n                    \"The volume of a note\",\n                    \"The numbered position of a note within a scale (1-7)\",\n                    \"The frequency in Hz\",\n                    \"The octave number\"\n                ],\n                answer: 1,\n                explain: \"Scale degrees number the notes of a scale from 1 (tonic) to 7 (leading tone). Using numbers means the same patterns apply regardless of key.\",\n                hint: \"1 = home. 5 = tension. 7 = leading tone.\"\n            }\n        ]\n    },\n    {\n        slug: \"minor-scale\",\n        world: \"foundations\",\n        number: 19,\n        title: \"The Minor Scale\",\n        tagline: \"Darkness, mystery and emotional depth.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"The natural minor scale follows: W H W W H W W. Starting on A: A B C D E F G — the relative minor of C major, using the same notes but with A as home. Source: learningmusic.ableton.com/notes-and-scales\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Natural minor: W H W W H W W (darkest, most basic)\",\n                    \"Harmonic minor: raises the 7th by a semitone — dramatic pull to tonic\",\n                    \"Melodic minor: raises both 6th and 7th when ascending — smoother melodic motion\",\n                    \"Relative minor — every major key has a relative minor starting from the 6th degree\",\n                    \"Parallel minor — same root, different notes (C major vs C minor)\"\n                ]\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"Compared to the major scale, the minor scale has a lowered\",\n                options: [\n                    \"2nd degree\",\n                    \"3rd degree\",\n                    \"5th degree\",\n                    \"7th degree\"\n                ],\n                answer: 1,\n                explain: \"The minor scale lowers the 3rd degree by one semitone compared to major. This single change gives minor its darker quality.\",\n                hint: \"The 3rd degree is the key difference. Lower it and it gets sadder.\"\n            },\n            {\n                q: \"The relative minor of C major is\",\n                options: [\n                    \"C minor\",\n                    \"A minor\",\n                    \"E minor\",\n                    \"G minor\"\n                ],\n                answer: 1,\n                explain: \"Every major key has a relative minor starting on the 6th scale degree. The 6th degree of C major is A, so A minor is its relative minor.\",\n                hint: \"Go to the 6th note of C major (C-D-E-F-G-A). Start there = A minor.\"\n            },\n            {\n                q: \"The harmonic minor scale is distinctive because it has\",\n                options: [\n                    \"A lowered 5th\",\n                    \"A raised 7th creating a 1.5-step interval\",\n                    \"No sharps or flats\",\n                    \"A raised 3rd\"\n                ],\n                answer: 1,\n                explain: \"Harmonic minor raises the 7th by a semitone, creating a gap of 1.5 steps between the 6th and 7th degrees. Very common in flamenco, classical, and metal.\",\n                hint: \"The exotic sounding minor. Eastern or dramatic flavour.\"\n            },\n            {\n                q: \"Which genres frequently use minor keys?\",\n                options: [\n                    \"Happy birthday songs only\",\n                    \"Dark melancholic dramatic music — metal, dark EDM, blues, film scores\",\n                    \"Only classical music\",\n                    \"Only jazz\"\n                ],\n                answer: 1,\n                explain: \"Minor keys are used wherever darkness, sadness, tension or drama are needed.\",\n                hint: \"Darkness = minor. Think sad film music.\"\n            }\n        ]\n    },\n    {\n        slug: \"intervals\",\n        world: \"foundations\",\n        number: 20,\n        title: \"Intervals\",\n        tagline: \"The distance between notes and why it matters.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"An interval is the distance in pitch between two notes. Intervals determine whether two notes sound stable or tense, consonant or dissonant. Every melody, chord and harmony is built from specific intervals. Source: learningmusic.ableton.com/notes-and-scales\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Minor 2nd (1 semitone) — very dissonant, tense (Jaws theme)\",\n                    \"Major 2nd (2 semitones) — stepwise motion, neutral\",\n                    \"Minor 3rd (3 semitones) — minor colour, slightly sad\",\n                    \"Major 3rd (4 semitones) — bright, major colour, stable\",\n                    \"Perfect 4th (5 semitones) — strong, open\",\n                    \"Tritone (6 semitones) — most dissonant, devil interval\",\n                    \"Perfect 5th (7 semitones) — powerful, open, stable\",\n                    \"Octave (12 semitones) — perfect consonance\"\n                ]\n            }\n        ],\n        sim: {\n            type: \"ear-training\"\n        },\n        quiz: [\n            {\n                q: \"How many semitones is a perfect fifth?\",\n                options: [\n                    \"5\",\n                    \"6\",\n                    \"7\",\n                    \"8\"\n                ],\n                answer: 2,\n                explain: \"A perfect 5th = 7 semitones. From C to G is 7 semitones. One of the most stable powerful intervals.\",\n                hint: \"C to G. Count: C C# D D# E F F# G = 7.\"\n            },\n            {\n                q: \"The devil interval — most dissonant — is the\",\n                options: [\n                    \"Major 3rd\",\n                    \"Perfect 5th\",\n                    \"Tritone (diminished 5th)\",\n                    \"Minor 2nd\"\n                ],\n                answer: 2,\n                explain: \"The tritone (6 semitones — exactly half an octave) is the most dissonant interval. Historically called diabolus in musica.\",\n                hint: \"Exactly halfway between unison and octave — maximum tension.\"\n            },\n            {\n                q: \"A power chord is built from\",\n                options: [\n                    \"Root major 3rd and 5th\",\n                    \"Root and 5th only — no 3rd\",\n                    \"Root minor 3rd and 5th\",\n                    \"Root and octave only\"\n                ],\n                answer: 1,\n                explain: \"Power chord = root + perfect 5th only. No 3rd = no major or minor quality — just raw powerful ambiguity.\",\n                hint: \"Root + 5th. No 3rd. Ambiguous = powerful.\"\n            },\n            {\n                q: \"Consonant intervals feel\",\n                options: [\n                    \"Tense and unstable\",\n                    \"Stable and pleasant — they do not need to resolve\",\n                    \"Always louder\",\n                    \"Only usable in major keys\"\n                ],\n                answer: 1,\n                explain: \"Consonant intervals (octaves, 5ths, 4ths, 3rds) feel stable and complete. Dissonant intervals create tension wanting resolution.\",\n                hint: \"Consonant = at rest. Dissonant = restless needing to move.\"\n            }\n        ]\n    },\n    {\n        slug: \"pentatonic-scales\",\n        world: \"foundations\",\n        number: 21,\n        title: \"Pentatonic Scales\",\n        tagline: \"Five notes. Every culture. Infinite melodies.\",\n        xp: 40,\n        badge: {\n            slug: \"pentatonic-explorer\",\n            name: \"Pentatonic Explorer\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"The pentatonic scale is a five-note scale that appears in virtually every musical culture on earth independently. It works because it avoids the most dissonant intervals. Source: learningmusic.ableton.com/notes-and-scales\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Major pentatonic (C): C D E G A — bright uplifting country/folk/pop\",\n                    \"Minor pentatonic (A): A C D E G — bluesy dark rock/blues/R&B/hip-hop\",\n                    \"Works over major AND minor chords — very flexible\",\n                    \"No tritone interval — no wrong combinations between these 5 notes\",\n                    \"Chinese, Celtic, African, Native American scales are all pentatonic variants\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"If stuck on a melody and nothing sounds right, go pentatonic. Five notes, all consonant. Hard to make a mistake. Add notes from the full scale back in one at a time once you have the contour.\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"How many notes does a pentatonic scale have?\",\n                options: [\n                    \"4\",\n                    \"5\",\n                    \"6\",\n                    \"7\"\n                ],\n                answer: 1,\n                explain: \"Penta = five. A pentatonic scale has 5 notes compared to 7 in a standard major or minor scale.\",\n                hint: \"Pentagon has 5 sides. Pentatonic has 5 notes.\"\n            },\n            {\n                q: \"The minor pentatonic scale is widely used in\",\n                options: [\n                    \"Classical string quartets\",\n                    \"Blues, rock, and hip-hop lead playing\",\n                    \"12-tone serial music\",\n                    \"Indian classical raga\"\n                ],\n                answer: 1,\n                explain: \"The minor pentatonic is the foundation of blues, rock, and much R&B/hip-hop melodic improvisation.\",\n                hint: \"Blues guitar. Rock riffs. Sweet Home Chicago. All minor pentatonic.\"\n            },\n            {\n                q: \"Why do pentatonic scales appear in so many cultures independently?\",\n                options: [\n                    \"They were invented in China\",\n                    \"They avoid the most dissonant intervals — they are naturally consonant\",\n                    \"They use only 5 fingers\",\n                    \"They are easier to write down\"\n                ],\n                answer: 1,\n                explain: \"Pentatonic scales remove the most dissonant intervals. The remaining notes are all consonant with each other.\",\n                hint: \"No wrong notes in pentatonic — it is harmonically safe.\"\n            },\n            {\n                q: \"The major pentatonic is the major scale with which degrees removed?\",\n                options: [\n                    \"1st and 5th\",\n                    \"3rd and 7th\",\n                    \"4th and 7th\",\n                    \"2nd and 6th\"\n                ],\n                answer: 2,\n                explain: \"Major pentatonic = major scale minus the 4th and 7th degrees — the most dissonant members.\",\n                hint: \"Remove the two most tense notes: the 4 and the 7.\"\n            }\n        ]\n    },\n    {\n        slug: \"melody-writing\",\n        world: \"foundations\",\n        number: 22,\n        title: \"Writing a Melody\",\n        tagline: \"Contour, phrases and what makes a hook.\",\n        xp: 50,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A great melody is a small story told in pitch and rhythm. It has contour (going up and down), phrasing (breathing in and out), and usually a climax and resolution. Source: learningmusic.ableton.com/notes-and-scales\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Stepwise motion — notes move to adjacent scale degrees (smooth, vocal-friendly)\",\n                    \"Leaps — notes jump by a 3rd or more (dramatic, interesting)\",\n                    \"Phrase — a complete melodic idea like a sentence (usually 2 or 4 bars)\",\n                    \"Question and answer — first phrase ends unresolved second completes it\",\n                    \"Motif — a short 3-5 note idea that repeats and transforms throughout the melody\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"The best hooks often have a surprising note — one that sits just outside the obvious scale or lands on an unexpected beat. Surprise creates memorability. Predictability creates familiarity. You need both.\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"Melodic contour refers to\",\n                options: [\n                    \"The key a melody is in\",\n                    \"The overall shape — the pattern of rising and falling pitches\",\n                    \"How many notes are in the melody\",\n                    \"The tempo of the melody\"\n                ],\n                answer: 1,\n                explain: \"Contour is the shape of a melody over time — whether it rises, falls, arches, waves, or leaps.\",\n                hint: \"Draw the melody as a line graph. What shape does it make?\"\n            },\n            {\n                q: \"A melodic motif is\",\n                options: [\n                    \"A full verse melody\",\n                    \"A short recognisable 3-5 note idea used as a building block\",\n                    \"A chord sequence\",\n                    \"A type of drum pattern\"\n                ],\n                answer: 1,\n                explain: \"A motif is a short melodic cell that forms the seed of a melody. It can be repeated, inverted, transposed, or developed.\",\n                hint: \"Think: da da da DAAA. Short. Recognisable. Repeated.\"\n            },\n            {\n                q: \"A question and answer melody structure means\",\n                options: [\n                    \"The first verse is a question the chorus is the answer\",\n                    \"The first phrase ends with tension the second resolves it\",\n                    \"Two different singers trade lines\",\n                    \"An instrumental and vocal trade off\"\n                ],\n                answer: 1,\n                explain: \"The question phrase ends on an unresolved note. The answer phrase resolves to the tonic.\",\n                hint: \"First phrase: rises feels unfinished. Second phrase: falls home.\"\n            },\n            {\n                q: \"What makes a melodic hook memorable?\",\n                options: [\n                    \"Being as complex as possible\",\n                    \"Using as many notes as possible\",\n                    \"A balance of surprise and familiarity\",\n                    \"Using only pentatonic notes\"\n                ],\n                answer: 2,\n                explain: \"The sweet spot is predictable enough to follow but surprising enough to be interesting. One unexpected note in an otherwise simple phrase is the classic formula.\",\n                hint: \"Simple + one surprise = memorable. Complex throughout = forgettable.\"\n            }\n        ]\n    },\n    {\n        slug: \"ear-training\",\n        world: \"foundations\",\n        number: 23,\n        title: \"Ear Training Basics\",\n        tagline: \"Training your ear to recognise what you hear.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Ear training connects what you hear to what you know — recognising intervals, chords, scale degrees, and rhythms by sound alone. Source: learningmusic.ableton.com\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Relative pitch — recognising the relationship between notes (interval recognition)\",\n                    \"Interval recognition — hearing the colour of each interval\",\n                    \"Chord quality recognition — hearing major vs minor vs diminished vs dominant 7th\",\n                    \"Rhythmic dictation — clapping back what you hear, identifying note values\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Use reference songs for interval recognition. A major 2nd sounds like Happy Birthday. A perfect 4th sounds like Here Comes the Bride. A perfect 5th sounds like the Star Wars theme. Anchor each interval to a song you know.\"\n            }\n        ],\n        sim: {\n            type: \"ear-training\"\n        },\n        quiz: [\n            {\n                q: \"Relative pitch means\",\n                options: [\n                    \"Having perfect pitch\",\n                    \"Recognising the intervals and relationships between notes by ear\",\n                    \"Always singing at the correct pitch\",\n                    \"Using a reference pitch before playing\"\n                ],\n                answer: 1,\n                explain: \"Relative pitch is the ability to identify intervals and scale degrees by ear — knowing the relationship not necessarily the exact note name.\",\n                hint: \"Relative = in relation to other notes. Not absolute.\"\n            },\n            {\n                q: \"A good strategy for recognising a major 2nd interval is\",\n                options: [\n                    \"Studying music theory books\",\n                    \"Memorising the formula\",\n                    \"Associating it with the opening of Happy Birthday\",\n                    \"Practising scales daily\"\n                ],\n                answer: 2,\n                explain: \"Reference songs are the most effective way to recognise intervals by ear. Happy Birthday opens with a major 2nd.\",\n                hint: \"Happy Bir-THDAY. The first two notes = major 2nd.\"\n            },\n            {\n                q: \"The main benefit of ear training for a producer is\",\n                options: [\n                    \"Memorising music theory\",\n                    \"Shrinking the gap between what you can imagine and what you can execute\",\n                    \"Learning to read sheet music\",\n                    \"Playing faster\"\n                ],\n                answer: 1,\n                explain: \"Ear training connects your inner musical imagination to your technical execution.\",\n                hint: \"Imagine a melody then find it on the keyboard. Ear training makes that faster.\"\n            },\n            {\n                q: \"How often should you do ear training for it to be effective?\",\n                options: [\n                    \"Once a week for 2 hours\",\n                    \"Daily even just 10 minutes\",\n                    \"Only when learning a new instrument\",\n                    \"Only before recording sessions\"\n                ],\n                answer: 1,\n                explain: \"Short daily ear training sessions are far more effective than occasional long sessions.\",\n                hint: \"Consistency beats intensity. Daily drills not rare marathons.\"\n            }\n        ]\n    },\n    {\n        slug: \"transposition-modes\",\n        world: \"foundations\",\n        number: 24,\n        title: \"Transposition and Modes\",\n        tagline: \"Moving music to a new key and new moods.\",\n        xp: 40,\n        badge: {\n            slug: \"key-changer\",\n            name: \"Key Changer\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Transposition means moving a melody or chord up or down by a fixed interval — keeping all relationships the same at a different pitch level. Source: Ableton Live manual — Transposing MIDI.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Ionian (major) — bright stable happy\",\n                    \"Dorian — minor but with a bright 6th — jazz funk soul (Miles Davis So What)\",\n                    \"Phrygian — dark Spanish flamenco flavour\",\n                    \"Lydian — dreamy floating superhero feel (John Williams themes)\",\n                    \"Mixolydian — major but with a flat 7th — rock blues Beatles\",\n                    \"Aeolian (natural minor) — dark melancholic\",\n                    \"Locrian — extremely tense rarely used\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Dorian is the most used non-major non-minor mode in production. Minor-ish but with a brighter 6th that lifts it out of pure sadness. Funk, soul, and much jazz uses Dorian constantly.\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"Transposing a MIDI region by +5 semitones means\",\n                options: [\n                    \"Making it louder by 5 dB\",\n                    \"Moving every note 5 semitones higher\",\n                    \"Increasing the tempo by 5 BPM\",\n                    \"Adding 5 notes to the melody\"\n                ],\n                answer: 1,\n                explain: \"Transposition shifts every note by a fixed interval. +5 semitones = every note goes up 5 semitones (a perfect 4th higher). Source: Ableton Live manual.\",\n                hint: \"Transpose = shift. +5 semitones = 5 half-steps up.\"\n            },\n            {\n                q: \"The Dorian mode is best described as\",\n                options: [\n                    \"A major scale starting from G\",\n                    \"A minor scale with a raised brighter 6th degree\",\n                    \"The same as the natural minor scale\",\n                    \"A scale with a tritone as the 2nd note\"\n                ],\n                answer: 1,\n                explain: \"Dorian = natural minor with a raised 6th. Darker than major but brighter than Aeolian. Widely used in jazz funk and soul.\",\n                hint: \"Minor but not quite as dark. That raised 6th is the difference.\"\n            },\n            {\n                q: \"Which mode sounds dreamy or floating due to its raised 4th?\",\n                options: [\n                    \"Phrygian\",\n                    \"Dorian\",\n                    \"Lydian\",\n                    \"Mixolydian\"\n                ],\n                answer: 2,\n                explain: \"Lydian has a raised 4th degree. This creates a dreamy floating otherworldly quality — used extensively in film scoring.\",\n                hint: \"Many superhero and adventure film themes use Lydian.\"\n            },\n            {\n                q: \"Mixolydian is the same as a major scale but with a\",\n                options: [\n                    \"Lowered 3rd\",\n                    \"Lowered 5th\",\n                    \"Raised 6th\",\n                    \"Lowered 7th\"\n                ],\n                answer: 3,\n                explain: \"Mixolydian = major scale with a flat 7th. Blues rock and many Beatles songs imply Mixolydian.\",\n                hint: \"Major but with a flat 7. Blues rock Beatles — all over Mixolydian.\"\n            }\n        ]\n    }\n];\nconst harmonyPath = [\n    {\n        slug: \"what-are-chords\",\n        world: \"foundations\",\n        number: 25,\n        title: \"What Are Chords?\",\n        tagline: \"Multiple notes together and the feeling they create.\",\n        xp: 40,\n        badge: {\n            slug: \"chord-builder\",\n            name: \"Chord Builder\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A chord is three or more notes played simultaneously. The combination creates a harmonic colour — major chords sound bright and stable, minor chords darker, diminished chords tense. Source: learningmusic.ableton.com/chords\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Root position — lowest note is the root (C E G)\",\n                    \"First inversion — lowest note is the 3rd (E G C)\",\n                    \"Second inversion — lowest note is the 5th (G C E)\",\n                    \"Spread voicing — notes across octaves\",\n                    \"Close voicing — notes packed within one octave\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"In production, chords are often voiced beyond the basic triad. The same C major chord sounds completely different depending on how the notes are arranged (voicing).\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"A triad is built from\",\n                options: [\n                    \"Two notes\",\n                    \"Three notes stacked in thirds\",\n                    \"Four notes\",\n                    \"All seven scale notes\"\n                ],\n                answer: 1,\n                explain: \"A triad = root + 3rd + 5th — the foundation of all Western harmony. Source: learningmusic.ableton.com/chords\",\n                hint: \"Tri = three. Three notes stacked in thirds.\"\n            },\n            {\n                q: \"Chord voicing affects\",\n                options: [\n                    \"The key of the chord\",\n                    \"How the notes are arranged — the sound and texture\",\n                    \"The tempo\",\n                    \"The scale\"\n                ],\n                answer: 1,\n                explain: \"Same notes in different arrangements = very different sound. Voicing is one of the most powerful arrangement tools.\",\n                hint: \"Same notes different arrangement. Completely changes the feel.\"\n            },\n            {\n                q: \"A power chord contains\",\n                options: [\n                    \"Root, 3rd and 5th\",\n                    \"Root and 5th only — no 3rd\",\n                    \"Root and 3rd only\",\n                    \"Root and octave only\"\n                ],\n                answer: 1,\n                explain: \"Power chord = root + perfect 5th. No 3rd = no major or minor quality — just raw powerful ambiguity.\",\n                hint: \"Root + 5th. No 3rd. Ambiguous = powerful.\"\n            },\n            {\n                q: \"First inversion of C major (C E G) has __ as the lowest note.\",\n                options: [\n                    \"C\",\n                    \"E\",\n                    \"G\",\n                    \"A\"\n                ],\n                answer: 1,\n                explain: \"First inversion = 3rd on the bottom. For C major the 3rd is E. So first inversion = E G C.\",\n                hint: \"First inversion = 3rd on the bottom. For C major the 3rd is E.\"\n            }\n        ]\n    },\n    {\n        slug: \"chord-types\",\n        world: \"foundations\",\n        number: 26,\n        title: \"Chord Types\",\n        tagline: \"Major, minor, diminished, augmented and beyond.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Different chord types produce different emotional qualities. Source: learningmusic.ableton.com/chords/chords.html\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Major triad — bright stable happy. Root + major 3rd + 5th\",\n                    \"Minor triad — dark sad. Root + minor 3rd + 5th\",\n                    \"Diminished — very tense. Root + minor 3rd + diminished 5th\",\n                    \"Augmented — dreamy floating. Root + major 3rd + augmented 5th\",\n                    \"Dominant 7th (V7) — major triad + minor 7th. Bluesy tense wants to resolve.\",\n                    \"Major 7th — rich lush jazz. Major triad + major 7th\",\n                    \"Minor 7th — smooth soulful. Minor triad + minor 7th\",\n                    \"Sus2/Sus4 — open ambiguous modern. 3rd replaced by 2nd or 4th\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Sus chords (Sus2, Sus4) are everywhere in pop and electronic music — they create openness and modernity without the jazz complexity of full 7th chord harmony.\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"A minor triad differs from major by\",\n                options: [\n                    \"Having an extra note\",\n                    \"Lowering the 5th\",\n                    \"Lowering the 3rd by one semitone\",\n                    \"Raising the root\"\n                ],\n                answer: 2,\n                explain: \"Major 3rd = 4 semitones (bright). Minor 3rd = 3 semitones (dark). One semitone change transforms the emotional quality. Source: learningmusic.ableton.com\",\n                hint: \"Lower the middle note of a major chord by one semitone = minor.\"\n            },\n            {\n                q: \"A dominant 7th chord is used primarily to\",\n                options: [\n                    \"Stay stable\",\n                    \"Create tension that strongly resolves to the next chord\",\n                    \"Add sadness\",\n                    \"Replace the tonic\"\n                ],\n                answer: 1,\n                explain: \"The V7 chord creates intense drive to resolve to the tonic. Its tritone interval creates the tension.\",\n                hint: \"G7 desperately wants to resolve to C.\"\n            },\n            {\n                q: \"What makes a diminished chord tense?\",\n                options: [\n                    \"It has four notes\",\n                    \"It contains a tritone interval\",\n                    \"It uses the major 3rd\",\n                    \"It is played faster\"\n                ],\n                answer: 1,\n                explain: \"Diminished triad = minor 3rd + diminished 5th (tritone). The tritone is the most dissonant interval.\",\n                hint: \"Tritone = devil interval. Diminished chords are full of them.\"\n            },\n            {\n                q: \"Sus chords replace the 3rd with\",\n                options: [\n                    \"The 7th\",\n                    \"The 2nd or 4th degree\",\n                    \"An octave\",\n                    \"Nothing\"\n                ],\n                answer: 1,\n                explain: \"Suspended chords replace the 3rd with the 2nd or 4th. Since the 3rd determines major/minor quality, Sus chords are tonally ambiguous.\",\n                hint: \"Sus = suspended. The 3rd is suspended.\"\n            }\n        ]\n    },\n    {\n        slug: \"chord-progressions\",\n        world: \"foundations\",\n        number: 27,\n        title: \"Chord Progressions\",\n        tagline: \"The journey through harmony — how chords move.\",\n        xp: 50,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A chord progression is a sequence of chords creating tension and release. Roman numerals describe progressions universally. Source: learningmusic.ableton.com/chords/chords.html\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"I-V-vi-IV — the most used progression: C G Am F (Let It Be, Africa, etc.)\",\n                    \"I-IV-V-I — 12-bar blues: foundation of rock blues country\",\n                    \"ii-V-I — the jazz cadence (Dm7 G7 Cmaj7): strongest resolution in jazz\",\n                    \"I-vi-IV-V — 50s progression: C Am F G\",\n                    \"vi-IV-I-V — minor first: Am F C G — slightly darker\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"The emotional power of a progression comes from expectation and resolution. V always wants to go to I. Subvert that (V to vi instead of I) and you create a deceptive cadence.\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"In C major what chord is the V chord?\",\n                options: [\n                    \"F major\",\n                    \"G major\",\n                    \"A minor\",\n                    \"D minor\"\n                ],\n                answer: 1,\n                explain: \"V chord built on the 5th degree. In C major the 5th is G. G major is the V chord.\",\n                hint: \"C D E F G. 5th note is G.\"\n            },\n            {\n                q: \"The I-V-vi-IV progression is notable because\",\n                options: [\n                    \"It was invented in the 1960s\",\n                    \"It has been used in thousands of hit songs\",\n                    \"It only works in minor keys\",\n                    \"It must be played slowly\"\n                ],\n                answer: 1,\n                explain: \"I-V-vi-IV is the most ubiquitous chord progression in popular music — spans multiple decades and genres. Source: learningmusic.ableton.com\",\n                hint: \"Google four chord songs.\"\n            },\n            {\n                q: \"A deceptive cadence is when V resolves to\",\n                options: [\n                    \"I as expected\",\n                    \"vi instead of I creating surprise\",\n                    \"IV\",\n                    \"The same chord\"\n                ],\n                answer: 1,\n                explain: \"V to vi instead of V to I. The ear expects I but gets vi — emotional ambiguity.\",\n                hint: \"The ear expects I. It gets vi instead. Deceived.\"\n            },\n            {\n                q: \"Roman numerals in chord progressions are useful because\",\n                options: [\n                    \"They look professional\",\n                    \"They describe chord relationships independent of key\",\n                    \"They only apply to classical music\",\n                    \"They describe chord volume\"\n                ],\n                answer: 1,\n                explain: \"Roman numerals describe relationships independently of key. I-IV-V-I in C has the same relationships as in G major.\",\n                hint: \"Same pattern any key.\"\n            }\n        ]\n    },\n    {\n        slug: \"keys-tonality\",\n        world: \"foundations\",\n        number: 28,\n        title: \"Keys and Tonality\",\n        tagline: \"Where home is and why it matters.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A key establishes a tonal centre — a home base note and chord that everything gravitates toward. Source: learningmusic.ableton.com/notes-and-scales\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Tonic (I) — home. Most stable chord.\",\n                    \"Dominant (V) — farthest from home. Maximum tension.\",\n                    \"Subdominant (IV) — away but not tense. Reflective.\",\n                    \"Key signature — the sharps or flats defining the 7 notes in the key\",\n                    \"Modulation — deliberately moving from one key to another during a song\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"In Ableton Live 12, Scale Awareness highlights only the notes of your chosen scale in the piano roll — making it easier to write melodies and chords that stay in key. Source: Ableton Live 12 manual.\"\n            }\n        ],\n        sim: {\n            type: \"scale-aware\"\n        },\n        quiz: [\n            {\n                q: \"The tonic of a key is\",\n                options: [\n                    \"The highest note in the scale\",\n                    \"The home base chord/note that everything gravitates toward\",\n                    \"The fastest part\",\n                    \"The bass note\"\n                ],\n                answer: 1,\n                explain: \"The tonic is the note and chord that feels like home. Moving away creates tension; returning creates resolution.\",\n                hint: \"Tonic = home.\"\n            },\n            {\n                q: \"The dominant (V) chord creates\",\n                options: [\n                    \"A sense of rest\",\n                    \"Maximum harmonic tension and a strong pull back to tonic\",\n                    \"A neutral feeling\",\n                    \"A minor colour\"\n                ],\n                answer: 1,\n                explain: \"The dominant is the most harmonically tense chord. It contains the leading tone which pulls strongly up to the tonic.\",\n                hint: \"Dominant to tonic. Pull to release.\"\n            },\n            {\n                q: \"When a song modulates it\",\n                options: [\n                    \"Changes tempo\",\n                    \"Changes time signature\",\n                    \"Moves from one key to another during the song\",\n                    \"Adds more instruments\"\n                ],\n                answer: 2,\n                explain: \"Modulation is a deliberate key change mid-song. Classic: up a whole step before the final chorus.\",\n                hint: \"Whitney Houston raising the key before the final chorus = modulation.\"\n            },\n            {\n                q: \"How many keys major and minor are there in total?\",\n                options: [\n                    \"12\",\n                    \"14\",\n                    \"24\",\n                    \"48\"\n                ],\n                answer: 2,\n                explain: \"12 major + 12 minor = 24 keys total.\",\n                hint: \"12 major + 12 minor = 24.\"\n            }\n        ]\n    },\n    {\n        slug: \"tension-resolution\",\n        world: \"foundations\",\n        number: 29,\n        title: \"Tension and Resolution\",\n        tagline: \"The push and pull that makes music go somewhere.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Music creates emotional engagement through tension and resolution — the same mechanism as storytelling. Source: learningmusic.ableton.com\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Harmonic tension — dissonant chords resolve to consonant chords\",\n                    \"Melodic tension — the leading tone (7th degree) resolves up to the tonic\",\n                    \"Rhythmic tension — syncopation resolves to the downbeat\",\n                    \"Dynamic tension — quiet builds to loud then resolves\",\n                    \"Textural tension — complexity resolves by stripping back\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"In electronic music, the build-up (8-16 bars) followed by the drop (sudden resolution) is the most powerful structural device. All tools — filter sweeps risers crashes — exist to maximise this tension-release ratio.\"\n            }\n        ],\n        sim: {\n            type: \"none\"\n        },\n        quiz: [\n            {\n                q: \"In music resolution means\",\n                options: [\n                    \"Increasing volume\",\n                    \"Moving from tension to consonance — arriving at the stable point\",\n                    \"Changing the key\",\n                    \"Ending the song\"\n                ],\n                answer: 1,\n                explain: \"Resolution is movement from tension to stability. V to I is the fundamental example.\",\n                hint: \"The satisfying arrival. Like a story reaching its conclusion.\"\n            },\n            {\n                q: \"In electronic music what is the drop?\",\n                options: [\n                    \"A quiet interlude\",\n                    \"The moment of maximum energy arrival after a build-up\",\n                    \"A tempo change\",\n                    \"The ending\"\n                ],\n                answer: 1,\n                explain: \"The drop is when tension releases as the full beat bass and arrangement returns at maximum energy.\",\n                hint: \"Build up everything then it DROPS. Maximum release.\"\n            },\n            {\n                q: \"The leading tone (7th scale degree) creates tension because\",\n                options: [\n                    \"It is the loudest note\",\n                    \"It is only a semitone below the tonic and wants to resolve upward\",\n                    \"It has a lower frequency\",\n                    \"It is outside the scale\"\n                ],\n                answer: 1,\n                explain: \"The leading tone is only one semitone below the tonic. This proximity creates a magnetic pull to resolve.\",\n                hint: \"B to C. One semitone up. The ear demands it.\"\n            },\n            {\n                q: \"A filter sweep creates tension by\",\n                options: [\n                    \"Adding reverb\",\n                    \"Gradually removing frequencies creating a muffled tunnel effect before the drop\",\n                    \"Changing the key\",\n                    \"Slowing the tempo\"\n                ],\n                answer: 1,\n                explain: \"A closing filter progressively removes high frequencies. When it opens at the drop the energy release is massive.\",\n                hint: \"Muffled then building then OPEN. Classic pre-drop technique.\"\n            }\n        ]\n    },\n    {\n        slug: \"harmony-in-production\",\n        world: \"foundations\",\n        number: 30,\n        title: \"Harmony in Production\",\n        tagline: \"How to use chords in your tracks practically.\",\n        xp: 40,\n        badge: {\n            slug: \"harmony-maker\",\n            name: \"Harmony Maker\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Understanding harmony theoretically is one thing. Applying it in a session is another. Source: learningmusic.ableton.com/chords\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Chord stabs — short rhythmically punchy chord hits (house disco funk)\",\n                    \"Pad — long sustained chord texture providing harmonic background\",\n                    \"Arpeggio — chord notes played individually in a pattern\",\n                    \"Bassline — root notes of chords with rhythmic elaboration\",\n                    \"Melodic top line — the melody that sits above the harmonic bed\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"In Ableton: use the Chord MIDI effect to automatically add intervals to single notes. Play one key and the device adds your chosen intervals — instant chord stabs. Source: Ableton Live manual — MIDI Effects.\"\n            }\n        ],\n        sim: {\n            type: \"piano-roll\"\n        },\n        quiz: [\n            {\n                q: \"A pad in electronic music is\",\n                options: [\n                    \"A drum hit\",\n                    \"A sustained textural chord sound providing harmonic background\",\n                    \"A short chord stab\",\n                    \"A type of compression\"\n                ],\n                answer: 1,\n                explain: \"A pad is a sustained harmonic texture — long notes providing the bed of harmony beneath melody and rhythm.\",\n                hint: \"Floaty sustained background harmony. Like a pillow for the melody.\"\n            },\n            {\n                q: \"An arpeggio plays chord notes\",\n                options: [\n                    \"All at once\",\n                    \"Individually in a repeating pattern\",\n                    \"In reverse always\",\n                    \"Only on the beat\"\n                ],\n                answer: 1,\n                explain: \"An arpeggio plays chord notes one at a time in a pattern. Ableton's Arpeggiator MIDI device does this automatically.\",\n                hint: \"Notes of the chord one at a time in a pattern. Like a harp.\"\n            },\n            {\n                q: \"Why check your mix in mono?\",\n                options: [\n                    \"To hear the stereo image\",\n                    \"To reveal phase cancellation and harmonic clashing between chord voices\",\n                    \"Mono sounds better\",\n                    \"To check reverb\"\n                ],\n                answer: 1,\n                explain: \"Mono summing reveals frequency clashing and phase cancellation hidden by stereo separation.\",\n                hint: \"Mono collapses stereo revealing frequency clashes.\"\n            },\n            {\n                q: \"The Chord MIDI effect in Ableton\",\n                options: [\n                    \"Adds reverb\",\n                    \"Adds intervals above a played note turning single notes into chords\",\n                    \"Random note variations\",\n                    \"Key detection\"\n                ],\n                answer: 1,\n                explain: \"Chord MIDI device adds configurable intervals above each note you play, transforming single notes into chords. Source: Ableton Live manual.\",\n                hint: \"Play one note hear a chord.\"\n            }\n        ]\n    },\n    {\n        slug: \"song-structure\",\n        world: \"foundations\",\n        number: 31,\n        title: \"Song Structure\",\n        tagline: \"Verse chorus bridge — the architecture of music.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Song structure is the roadmap of a piece of music — how the sections are ordered. Structure creates expectation, delivers payoff, and guides a listener through an emotional arc. Source: learningmusic.ableton.com/song-structure\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Intro — establishes mood before the main content\",\n                    \"Verse — storytelling section repeated with different lyrics\",\n                    \"Pre-chorus — builds energy into the chorus\",\n                    \"Chorus — highest energy most memorable section repeated multiple times\",\n                    \"Bridge — contrasting section that breaks repetition\",\n                    \"Outro — winds the track down\",\n                    \"Drop — in electronic music the main event — maximum energy section\"\n                ]\n            }\n        ],\n        sim: {\n            type: \"arrangement\"\n        },\n        quiz: [\n            {\n                q: \"The chorus of a song is typically\",\n                options: [\n                    \"The quietest section\",\n                    \"The highest-energy most melodically memorable section repeated several times\",\n                    \"The instrumental section\",\n                    \"The first section\"\n                ],\n                answer: 1,\n                explain: \"The chorus is the emotional and melodic peak — the section listeners most remember and sing along to.\",\n                hint: \"The part you keep singing after the song ends.\"\n            },\n            {\n                q: \"A bridge in song structure provides\",\n                options: [\n                    \"A way into the chorus\",\n                    \"Contrast and a break from repetition usually once later in the song\",\n                    \"The main verse melody\",\n                    \"An instrumental solo only\"\n                ],\n                answer: 1,\n                explain: \"A bridge is a contrasting section breaking the verse-chorus repetition pattern.\",\n                hint: \"Contrast before the final return.\"\n            },\n            {\n                q: \"In electronic music the drop is\",\n                options: [\n                    \"A tempo reduction\",\n                    \"The point of maximum energy arrival after a build-up\",\n                    \"A bass note going down\",\n                    \"The end\"\n                ],\n                answer: 1,\n                explain: \"The drop is the main event — when tension resolves as the full beat bass and arrangement returns.\",\n                hint: \"BUILD BUILD BUILD then it DROPS.\"\n            },\n            {\n                q: \"Why is structure important in electronic music?\",\n                options: [\n                    \"Required by copyright law\",\n                    \"Creates an emotional arc that engages listeners\",\n                    \"Reduces file size\",\n                    \"Makes mixing easier\"\n                ],\n                answer: 1,\n                explain: \"Structure transforms repeated material into a narrative. Even great loops get boring without structure.\",\n                hint: \"Structure creates the journey.\"\n            }\n        ]\n    },\n    {\n        slug: \"listening-actively\",\n        world: \"foundations\",\n        number: 32,\n        title: \"Listening Actively\",\n        tagline: \"Hear everything not just the song.\",\n        xp: 40,\n        badge: {\n            slug: \"active-listener\",\n            name: \"Active Listener\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Passive listening is enjoying music. Active listening is studying it — identifying the individual elements how they interact and what decisions were made. Source: learningmusic.ableton.com\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Solo each instrument mentally — what is the kick doing? The bass?\",\n                    \"Count bars — where do sections begin?\",\n                    \"Identify the key — major or minor?\",\n                    \"Listen to the mix — where is each instrument in the stereo field?\",\n                    \"Analyse structure — how long is the intro? When does the drop arrive?\",\n                    \"Notice effects — what is on the vocals? On the snare?\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Reference tracks are a professional production technique. Load a commercially released track in your target genre and regularly compare your mix to it. Every professional does this.\"\n            }\n        ],\n        sim: {\n            type: \"ear-training\"\n        },\n        quiz: [\n            {\n                q: \"Active listening means\",\n                options: [\n                    \"Listening with headphones\",\n                    \"Studying music analytically — identifying elements decisions and techniques\",\n                    \"Listening to new genres\",\n                    \"Listening at high volume\"\n                ],\n                answer: 1,\n                explain: \"Active listening is deliberate analytical engagement with music.\",\n                hint: \"Passive = enjoy. Active = study. What is the kick doing?\"\n            },\n            {\n                q: \"Using a reference track in production means\",\n                options: [\n                    \"Sampling the track directly\",\n                    \"Regularly comparing your mix to a professionally released track to check balance and quality\",\n                    \"Playing the track at a concert\",\n                    \"Using the track as a loop\"\n                ],\n                answer: 1,\n                explain: \"A reference track is your quality benchmark. Load it in your DAW and switch between your mix and it frequently.\",\n                hint: \"Your mix sounds great — until you put a pro track next to it.\"\n            },\n            {\n                q: \"When actively listening why focus on one element at a time?\",\n                options: [\n                    \"It is the only way to hear music properly\",\n                    \"Isolating one element reveals details masked when you listen to everything at once\",\n                    \"It makes the music slower\",\n                    \"It changes the mixing\"\n                ],\n                answer: 1,\n                explain: \"Focusing on one element lets you hear its specific character without the masking effect of everything playing together.\",\n                hint: \"Cocktail party effect — you cannot hear one conversation with too much background noise.\"\n            },\n            {\n                q: \"How does active listening improve music production?\",\n                options: [\n                    \"It directly improves technical skills\",\n                    \"It builds your library of sonic references — expanding your palette of possibilities\",\n                    \"It automatically makes mixes sound better\",\n                    \"It teaches you music theory\"\n                ],\n                answer: 1,\n                explain: \"Active listening builds a rich mental library of sounds structures techniques and references that feeds your production decisions.\",\n                hint: \"You cannot replicate what you have not heard. More active listening = bigger sonic vocabulary.\"\n            }\n        ]\n    }\n];\nconst techPath = [\n    {\n        slug: \"daw-explained\",\n        world: \"foundations\",\n        number: 33,\n        title: \"The DAW Explained\",\n        tagline: \"Your entire studio inside a laptop.\",\n        xp: 40,\n        badge: {\n            slug: \"studio-bootup\",\n            name: \"Studio Boot-Up\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A Digital Audio Workstation (DAW) is software that replaces an entire recording studio. Source: learningmusic.ableton.com\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Ableton Live — performance-focused, session grid + arrangement, electronic music standard\",\n                    \"FL Studio — pattern-based, hip-hop and electronic\",\n                    \"Logic Pro — Mac only, comprehensive\",\n                    \"Pro Tools — industry standard for professional recording studios\",\n                    \"GarageBand — free on Mac/iOS, beginner-friendly\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"The best DAW is the one you know. Pick one, learn it deeply.\"\n            }\n        ],\n        sim: {\n            type: \"interface-tour\"\n        },\n        quiz: [\n            {\n                q: \"What does DAW stand for?\",\n                options: [\n                    \"Digital Audio Workstation\",\n                    \"Drum And Wave machine\",\n                    \"Direct Audio Writer\",\n                    \"Dynamic Arrangement Window\"\n                ],\n                answer: 0,\n                explain: \"Digital Audio Workstation — software that replaces an entire recording studio.\",\n                hint: \"It is a workstation that works with digital audio.\"\n            },\n            {\n                q: \"Which DAW is the professional industry standard for recording studios?\",\n                options: [\n                    \"GarageBand\",\n                    \"FL Studio\",\n                    \"Pro Tools\",\n                    \"Ableton Live\"\n                ],\n                answer: 2,\n                explain: \"Pro Tools by Avid is the industry standard in professional recording studios.\",\n                hint: \"Walk into any pro recording studio. What is on the screen?\"\n            },\n            {\n                q: \"The best DAW for a beginner is\",\n                options: [\n                    \"Pro Tools\",\n                    \"The most expensive one\",\n                    \"The one you will actually use consistently and learn deeply\",\n                    \"Ableton Live always\"\n                ],\n                answer: 2,\n                explain: \"The best DAW is the one you know well. Consistency and depth of knowledge matter more than the tool.\",\n                hint: \"Consistency and depth of knowledge matter more than the tool itself.\"\n            },\n            {\n                q: \"What can ALL DAWs do?\",\n                options: [\n                    \"Only record audio\",\n                    \"Record audio, host virtual instruments, run effects, arrange and export\",\n                    \"Only create MIDI sequences\",\n                    \"Only mix live performances\"\n                ],\n                answer: 1,\n                explain: \"All DAWs — record audio, host virtual instruments, run effects, arrange, and export a stereo file.\",\n                hint: \"Record, arrange, mix, export. The universal DAW workflow.\"\n            }\n        ]\n    },\n    {\n        slug: \"midi-explained\",\n        world: \"foundations\",\n        number: 34,\n        title: \"MIDI Explained\",\n        tagline: \"The language that instruments use to talk to each other.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"MIDI (Musical Instrument Digital Interface) is a protocol — instructions, not audio: play note C4, velocity 80, for 500ms. Those instructions drive a virtual instrument to make the actual sound. Source: learningmusic.ableton.com\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Note On/Off — which note to play and when to stop\",\n                    \"Velocity — how hard the note was struck (0-127). Controls loudness and timbre.\",\n                    \"Channel — 1-16. Route different instruments to different channels.\",\n                    \"CC (Control Change) — values for knobs, mod wheel (0-127)\",\n                    \"Pitch Bend — a smooth continuous pitch variation message\",\n                    \"MIDI Clock — tempo synchronisation between devices\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"Because MIDI is instructions not sound, it is infinitely editable. Wrong note? Change it. Wrong tempo? Resize the region. Wrong instrument? Change the plugin. Source: Ableton Live manual.\"\n            }\n        ],\n        sim: {\n            type: \"midi-vs-audio\"\n        },\n        quiz: [\n            {\n                q: \"MIDI stores\",\n                options: [\n                    \"Actual recorded audio\",\n                    \"Instructions for playing notes — pitch timing velocity duration\",\n                    \"Compressed MP3 data\",\n                    \"Video data\"\n                ],\n                answer: 1,\n                explain: \"MIDI is not audio. It is a set of instructions. An instrument reads these and produces the actual sound.\",\n                hint: \"MIDI is sheet music. Instructions, not sound.\"\n            },\n            {\n                q: \"MIDI velocity controls\",\n                options: [\n                    \"The pitch of the note\",\n                    \"The volume of the channel\",\n                    \"How hard the note was struck — affecting loudness and often timbre\",\n                    \"The duration of the note\"\n                ],\n                answer: 2,\n                explain: \"Velocity (0-127) represents how hard a key was struck. Higher velocity = louder and often brighter.\",\n                hint: \"Hit a piano key hard vs soft. MIDI captures that difference.\"\n            },\n            {\n                q: \"Why is MIDI more flexible than recorded audio?\",\n                options: [\n                    \"It sounds better\",\n                    \"It can be edited note by note — tempo pitch instrument can all change without re-recording\",\n                    \"It uses less disk space always\",\n                    \"It automatically sounds professional\"\n                ],\n                answer: 1,\n                explain: \"Because MIDI is instructions you can change any parameter after recording: fix a wrong note, transpose the key, change the tempo, switch the instrument.\",\n                hint: \"Change the instrument, the tempo, the key — no re-recording.\"\n            },\n            {\n                q: \"CC (Control Change) messages carry\",\n                options: [\n                    \"Note pitches\",\n                    \"Tempo information\",\n                    \"Continuous parameter data like mod wheel, filter cutoff, volume\",\n                    \"Audio data\"\n                ],\n                answer: 2,\n                explain: \"MIDI CC messages carry continuous 0-127 values for parameters like modulation wheel, filter cutoff, volume, pan, and any assignable knob.\",\n                hint: \"Knob positions, pedal values, mod wheel — all CC messages.\"\n            }\n        ]\n    },\n    {\n        slug: \"digital-audio\",\n        world: \"foundations\",\n        number: 35,\n        title: \"Digital Audio\",\n        tagline: \"How sound becomes numbers and back again.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Digital audio converts continuous sound waves into sequences of numbers. Sample rate = how many times per second the audio is measured. Bit depth = how many values each sample can have. Source: Ableton Live manual.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Sample rate (kHz) — snapshots per second. 44.1 kHz = 44100 per second.\",\n                    \"Bit depth — 16-bit = 65536 values. 24-bit = 16777216 values.\",\n                    \"16-bit 44.1 kHz — CD quality. Sufficient for release.\",\n                    \"24-bit 48 kHz — standard for modern production. More headroom.\",\n                    \"WAV — uncompressed audio. Full quality. Large file size.\",\n                    \"MP3/AAC — compressed. Smaller files. Some quality loss.\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Record and produce at 24-bit for maximum dynamic range and headroom. Export as 16-bit WAV or 320kbps MP3 for distribution.\"\n            }\n        ],\n        sim: {\n            type: \"buffer-sim\"\n        },\n        quiz: [\n            {\n                q: \"What does sample rate mean?\",\n                options: [\n                    \"How many tracks can play simultaneously\",\n                    \"How many times per second the audio is measured and stored\",\n                    \"The tempo of the recording\",\n                    \"The bit depth\"\n                ],\n                answer: 1,\n                explain: \"Sample rate = measurements per second. 44100 Hz means the waveform is sampled 44100 times every second.\",\n                hint: \"44100 snapshots every second. Each is one sample.\"\n            },\n            {\n                q: \"Why is 44.1 kHz sufficient for human hearing?\",\n                options: [\n                    \"Chosen arbitrarily for CDs\",\n                    \"The Nyquist theorem: sample rate must be at least 2x the highest frequency you want to capture\",\n                    \"It reduces file size optimally\",\n                    \"It matches electrical frequency\"\n                ],\n                answer: 1,\n                explain: \"Nyquist theorem: to capture a frequency you need 2x sample rate. Humans hear to ~20 kHz so 40 kHz minimum. 44.1 kHz provides headroom above that.\",\n                hint: \"Nyquist: 2x the highest frequency. 20 kHz hearing needs 40 kHz sample rate minimum.\"\n            },\n            {\n                q: \"24-bit audio is preferred for production over 16-bit because\",\n                options: [\n                    \"It sounds brighter\",\n                    \"It provides more dynamic range and headroom for editing\",\n                    \"It uses less CPU\",\n                    \"Required by streaming platforms\"\n                ],\n                answer: 1,\n                explain: \"24-bit has a much lower noise floor than 16-bit. This extra headroom is crucial when applying multiple effects and making level adjustments.\",\n                hint: \"More bits = more dynamic range = more headroom.\"\n            },\n            {\n                q: \"WAV vs MP3\",\n                options: [\n                    \"WAV is newer\",\n                    \"WAV = uncompressed full quality large file. MP3 = lossy compressed smaller file some quality loss.\",\n                    \"MP3 is better quality always\",\n                    \"They are the same format\"\n                ],\n                answer: 1,\n                explain: \"WAV stores every sample uncompressed — full quality, large files. MP3 uses perceptual coding to achieve smaller files with some quality loss.\",\n                hint: \"WAV = perfect quality big file. MP3 = smaller file some quality lost.\"\n            }\n        ]\n    },\n    {\n        slug: \"samples-loops\",\n        world: \"foundations\",\n        number: 36,\n        title: \"Samples and Loops\",\n        tagline: \"Building blocks from recorded audio.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A sample is any piece of recorded audio used in a new production. A loop is a sample designed to repeat seamlessly — starts and ends at the exact same point so it cycles without gaps. Source: Ableton Live manual — Working with Samples.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"One-shot — single sound: drum hit, bass pluck, vocal stab\",\n                    \"Loop — seamless repeating audio: drum loop, bass loop, chord loop\",\n                    \"Sample pack — curated collection of related sounds, usually royalty-free\",\n                    \"Royalty-free — cleared for commercial use without per-use payments\",\n                    \"Warp — time-stretching audio in Ableton to match project tempo without pitch change\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"warn\",\n                text: \"Using someone else's released recording without clearance is copyright infringement. Sample packs labelled royalty-free are safe. Recognisable sections of released songs without clearance are not. Source: Ableton — learningmusic.ableton.com\"\n            }\n        ],\n        sim: {\n            type: \"warp-lab\"\n        },\n        quiz: [\n            {\n                q: \"A one-shot sample is\",\n                options: [\n                    \"A sample that loops\",\n                    \"A single sound that plays once — a drum hit, bass note, etc.\",\n                    \"A sample with one bar of audio\",\n                    \"A short vocal sample\"\n                ],\n                answer: 1,\n                explain: \"A one-shot is a discrete sound event that plays from start to finish without looping.\",\n                hint: \"One shot = plays once. No loop.\"\n            },\n            {\n                q: \"Audio warping in Ableton means\",\n                options: [\n                    \"Reversing the audio\",\n                    \"Time-stretching audio to match the project tempo without changing pitch\",\n                    \"Adding distortion\",\n                    \"Slicing the audio\"\n                ],\n                answer: 1,\n                explain: \"Warping time-stretches audio so it plays at the project BPM without changing pitch. Source: Ableton Live manual — Warping.\",\n                hint: \"Stretch time keep pitch. Fits the loop to your tempo.\"\n            },\n            {\n                q: \"Royalty-free sample packs are\",\n                options: [\n                    \"Always free to download\",\n                    \"Cleared for commercial use without per-use royalty payments\",\n                    \"Samples from before 1923\",\n                    \"Samples that cost royalties to use\"\n                ],\n                answer: 1,\n                explain: \"Royalty-free = cleared for commercial use. You can use the sounds in any production without additional per-use fees.\",\n                hint: \"Free OF royalties. Use commercially without per-song payments.\"\n            },\n            {\n                q: \"Why can using a recognisable section of a released song be problematic?\",\n                options: [\n                    \"It always improves the track\",\n                    \"Copyright infringement — you need clearance from rights holders\",\n                    \"Streaming platforms do not support samples\",\n                    \"Samples sound lower quality\"\n                ],\n                answer: 1,\n                explain: \"Recorded music is protected by copyright. Using without permission is infringement — takedowns and lawsuits.\",\n                hint: \"Their recording, their rights. Use without permission = copyright infringement.\"\n            }\n        ]\n    },\n    {\n        slug: \"signal-chain\",\n        world: \"foundations\",\n        number: 37,\n        title: \"The Signal Chain\",\n        tagline: \"How audio flows from source to your ears.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"A signal chain is the path audio takes from its source through all processing to its destination. Understanding signal flow is fundamental — it determines what order effects should go in and why certain things sound wrong. Source: Ableton Live manual.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Source — the original sound (voice, instrument, sample)\",\n                    \"Transducer — microphone or pickup converts sound to electrical signal\",\n                    \"Preamp — amplifies the weak signal to usable level\",\n                    \"ADC — audio interface converts analogue to digital for the DAW\",\n                    \"Channel processing — EQ, compression, effects on the individual track\",\n                    \"Bus processing — EQ/compression on grouped tracks\",\n                    \"Master bus — final processing before output (limiting, metering)\",\n                    \"DAC + speakers — converts digital back to analogue, drives speakers\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"Order matters. Distortion before EQ sounds completely different from EQ before distortion. Always consider the order of your effects chain.\"\n            }\n        ],\n        sim: {\n            type: \"routing-puzzle\"\n        },\n        quiz: [\n            {\n                q: \"Gain staging means\",\n                options: [\n                    \"Adding distortion\",\n                    \"Managing signal levels at each stage to keep the signal clean and avoid clipping\",\n                    \"Setting the master volume\",\n                    \"Automating volume\"\n                ],\n                answer: 1,\n                explain: \"Gain staging = setting appropriate levels at each stage. Strong enough to be clean, not so strong it clips.\",\n                hint: \"Not too loud (clips), not too quiet (noisy). At each stage.\"\n            },\n            {\n                q: \"Why does the order of effects matter?\",\n                options: [\n                    \"It does not — effects can go in any order\",\n                    \"Each effect processes the output of the previous one — order fundamentally changes the result\",\n                    \"It only matters for vintage gear\",\n                    \"It affects sample rate only\"\n                ],\n                answer: 1,\n                explain: \"Each effect receives the output of the previous one. Compressor before EQ vs EQ before compressor = completely different results.\",\n                hint: \"A-B-C is not the same as C-B-A.\"\n            },\n            {\n                q: \"An ADC does\",\n                options: [\n                    \"Amplifies the signal\",\n                    \"Converts analogue electrical signals to digital data a computer can process\",\n                    \"Adds compression\",\n                    \"Controls monitors\"\n                ],\n                answer: 1,\n                explain: \"An ADC (in your audio interface) converts the analogue electrical signal from a microphone or instrument into a digital binary stream.\",\n                hint: \"Analogue to Digital. What an audio interface input stage does.\"\n            },\n            {\n                q: \"The master bus is\",\n                options: [\n                    \"A hardware mixing desk\",\n                    \"The final stereo output path that carries the summed mix to speakers/export\",\n                    \"A MIDI bus\",\n                    \"A type of audio cable\"\n                ],\n                answer: 1,\n                explain: \"The master bus is where all tracks merge into the final stereo signal. Final limiting, metering, and overall shaping happen here.\",\n                hint: \"All tracks to master bus to speakers/export. The final destination.\"\n            }\n        ]\n    },\n    {\n        slug: \"effects-overview\",\n        world: \"foundations\",\n        number: 38,\n        title: \"Audio Effects Overview\",\n        tagline: \"EQ, compression, reverb, delay — what they all do.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Audio effects change a sound's character, feel, or place in a mix. The four most important: EQ (tonal shaping), compression (dynamic control), reverb (spatial placement), delay (time-based repetition). Source: Ableton Live manual — Audio Effects.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"EQ (Equaliser) — boosts or cuts specific frequency ranges\",\n                    \"Compression — reduces dynamic range. Controls punch and consistency.\",\n                    \"Reverb — simulates acoustic spaces. Places sound in a room or hall.\",\n                    \"Delay — repeats the signal after a set time. Rhythmic or textural.\",\n                    \"Saturation/Distortion — adds harmonic content. Warmth or aggression.\",\n                    \"Chorus/Flanger/Phaser — modulation effects that create thickness and movement.\",\n                    \"Limiter — hard ceiling that prevents the signal exceeding a set level.\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"The most common EQ mistake is too much boosting. Effective EQ is usually about cutting problem frequencies, not adding desired ones. Cut first, boost sparingly.\"\n            }\n        ],\n        sim: {\n            type: \"device-lab\"\n        },\n        quiz: [\n            {\n                q: \"The primary function of a compressor is\",\n                options: [\n                    \"Adding high-frequency air\",\n                    \"Creating spatial depth\",\n                    \"Reducing dynamic range — making loud parts quieter and quiet parts louder\",\n                    \"Removing frequencies\"\n                ],\n                answer: 2,\n                explain: \"Compression reduces dynamic range by attenuating signals above a threshold. This allows a higher average level — louder, punchier, more controlled. Source: Ableton Live manual — Compressor.\",\n                hint: \"Squeezing the dynamic range.\"\n            },\n            {\n                q: \"Insert vs send effects\",\n                options: [\n                    \"Insert effects are louder\",\n                    \"Insert = dedicated to one track. Send = shared — multiple tracks route to one effect.\",\n                    \"Send effects are higher quality\",\n                    \"Insert effects only work on drums\"\n                ],\n                answer: 1,\n                explain: \"Insert sits directly in the track signal chain. Send/return lets multiple tracks share one effect (usually reverb). Saves CPU and creates sonic cohesion.\",\n                hint: \"Insert = yours alone. Send = shared resource.\"\n            },\n            {\n                q: \"Saturation adds to a sound by\",\n                options: [\n                    \"Removing low frequencies\",\n                    \"Generating additional harmonic content — warmth or grit depending on the amount\",\n                    \"Creating spatial depth\",\n                    \"Making the sound quieter\"\n                ],\n                answer: 1,\n                explain: \"Saturation adds even and odd harmonics by pushing the signal slightly beyond linear range. A little = warmth and presence. A lot = aggressive distortion.\",\n                hint: \"Harmonics added = warmth, presence, character.\"\n            },\n            {\n                q: \"Why is EQ cutting often preferred over boosting?\",\n                options: [\n                    \"Cuts use less CPU\",\n                    \"Cutting removes problematic frequencies without adding gain and potential resonance issues\",\n                    \"Boosts change the tempo\",\n                    \"No difference\"\n                ],\n                answer: 1,\n                explain: \"Cutting removes problems cleanly. Boosting can increase gain and sometimes add resonance. Pro approach: cut what is wrong, boost sparingly.\",\n                hint: \"Subtractive = more natural. Remove the mud.\"\n            }\n        ]\n    },\n    {\n        slug: \"mixing-basics\",\n        world: \"foundations\",\n        number: 39,\n        title: \"Mixing Basics\",\n        tagline: \"Balancing all the parts into a whole.\",\n        xp: 40,\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"Mixing is the process of balancing all tracks in a production so they work cohesively. Source: learningmusic.ableton.com and Ableton Live manual — Mixing.\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Gain staging — set appropriate levels before processing (-18 dBFS average per track)\",\n                    \"Frequency balance — each instrument in its natural frequency range without excessive overlap\",\n                    \"Stereo placement — panning to place elements left/right; bass elements centred\",\n                    \"Dynamic consistency — compression to control unruly peaks\",\n                    \"Reverb/delay for depth — wet signals feel behind dry ones\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"tip\",\n                text: \"Mix at moderate volume (~75 dB SPL). Loud monitoring fools your ears about frequency balance. Regular breaks prevent fatigue. Check in mono regularly. Source: Ableton Live manual.\"\n            }\n        ],\n        sim: {\n            type: \"mixer\"\n        },\n        quiz: [\n            {\n                q: \"The goal of mixing is\",\n                options: [\n                    \"Making everything as loud as possible\",\n                    \"Ensuring every important element is clear, audible and in its right place\",\n                    \"Using as many effects as possible\",\n                    \"Matching a reference track\"\n                ],\n                answer: 1,\n                explain: \"Mixing is about clarity and balance — every element clear and sitting appropriately in the frequency and stereo field.\",\n                hint: \"Clarity, balance, each element in its space.\"\n            },\n            {\n                q: \"Why are bass elements kept centred in the stereo field?\",\n                options: [\n                    \"Music theory rule\",\n                    \"Bass frequencies are omnidirectional — our ears cannot locate them and stereo bass creates mono compatibility issues\",\n                    \"It makes them louder\",\n                    \"To save CPU\"\n                ],\n                answer: 1,\n                explain: \"Our ears cannot locate very low frequencies directionally. Panning bass into stereo creates phase issues when summed to mono.\",\n                hint: \"You cannot hear where bass comes from directionally. Keep it centred.\"\n            },\n            {\n                q: \"A track at -18 dBFS average before processing is\",\n                options: [\n                    \"Too quiet\",\n                    \"Correctly gain-staged — leaving headroom for effects and mixing moves\",\n                    \"Already at mix level\",\n                    \"Too loud\"\n                ],\n                answer: 1,\n                explain: \"-18 dBFS average leaves plenty of headroom for effects, compression, and summing without clipping.\",\n                hint: \"Headroom = space above average level before 0 dBFS ceiling.\"\n            },\n            {\n                q: \"Checking your mix in mono reveals\",\n                options: [\n                    \"The stereo width\",\n                    \"Phase cancellation and frequency clashes hidden by stereo separation\",\n                    \"The tempo\",\n                    \"Reverb levels\"\n                ],\n                answer: 1,\n                explain: \"Mono summing reveals frequency clashing and phase cancellation that stereo separation hides. A good mix works in both.\",\n                hint: \"Mono reveals problems stereo hides.\"\n            }\n        ]\n    },\n    {\n        slug: \"music-tech-integration\",\n        world: \"foundations\",\n        number: 40,\n        title: \"Putting It All Together\",\n        tagline: \"Sound, Rhythm, Melody, Harmony, Production = Music.\",\n        xp: 50,\n        badge: {\n            slug: \"foundations-complete\",\n            name: \"Foundations Complete\"\n        },\n        explainer: [\n            {\n                kind: \"lead\",\n                text: \"You now have the vocabulary of music. Sound, rhythm, melody, harmony, and production technology. These are not separate subjects — they are one integrated system. Source: learningmusic.ableton.com\"\n            },\n            {\n                kind: \"list\",\n                items: [\n                    \"Sound knowledge — helps you make sounds and hear what is wrong\",\n                    \"Rhythm knowledge — helps you programme beats and understand groove\",\n                    \"Melody knowledge — helps you write hooks and understand what makes them stick\",\n                    \"Harmony knowledge — helps you write chord progressions and understand emotional colour\",\n                    \"Tech knowledge — helps you translate musical ideas into a finished production\"\n                ]\n            },\n            {\n                kind: \"callout\",\n                tone: \"key\",\n                text: \"You do not need to master all of this before making music. Start now. Come back to these concepts when you encounter the problem they solve.\"\n            }\n        ],\n        sim: {\n            type: \"none\"\n        },\n        quiz: [\n            {\n                q: \"How does music theory relate to production?\",\n                options: [\n                    \"Theory must be mastered before producing\",\n                    \"Theory and production skill develop together — theory gives vocabulary production gives application\",\n                    \"Theory is only for classical musicians\",\n                    \"Theory is unnecessary with good ears\"\n                ],\n                answer: 1,\n                explain: \"Music theory and production practice reinforce each other. Theory gives vocabulary. Production experience shows which concepts are immediately useful.\",\n                hint: \"Theory + practice together, not theory first then practice.\"\n            },\n            {\n                q: \"The DJ World path primarily develops\",\n                options: [\n                    \"Sound synthesis skills\",\n                    \"How to select mix and play music for people — energy management and transition skills\",\n                    \"Advanced composition\",\n                    \"Music notation reading\"\n                ],\n                answer: 1,\n                explain: \"DJ World covers: selecting tracks, beatmatching and mixing, reading the crowd, managing energy over a set.\",\n                hint: \"DJing = playing music for people. Selection mixing energy timing.\"\n            },\n            {\n                q: \"The best time to start making music is\",\n                options: [\n                    \"After finishing all theory\",\n                    \"After buying professional equipment\",\n                    \"Now — make music while learning theory\",\n                    \"After 2 years of instrument lessons\"\n                ],\n                answer: 2,\n                explain: \"Start making music immediately and let practical problems drive your theory learning. Context makes theory stick.\",\n                hint: \"Start now. Theory makes more sense when you have real problems to solve.\"\n            },\n            {\n                q: \"Foundations knowledge of timbre frequency and harmonics is directly useful for\",\n                options: [\n                    \"Reading music faster\",\n                    \"EQ decisions — knowing which frequency range each instrument lives in and why sounds clash\",\n                    \"Typing faster in a DAW\",\n                    \"Reading music contracts\"\n                ],\n                answer: 1,\n                explain: \"Knowing the kick drum fundamental is 60-80 Hz and the bass guitar overlaps there explains why they clash. EQ is applied acoustics.\",\n                hint: \"Sound physics leads directly to EQ decisions.\"\n            }\n        ]\n    }\n];\nconst FOUNDATIONS_MISSIONS = [\n    ...soundPath,\n    ...rhythmPath,\n    ...melodyPath,\n    ...harmonyPath,\n    ...techPath\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./src/content/missions-foundations.ts\n");

